+// Constructor
+ValueKlass::ValueKlass(const ClassFileParser& parser)
+    : InstanceKlass(parser, ValueKlass::Kind, markWord::value_type_prototype()) {
+  assert(is_value_klass(), "sanity");
+  assert(prototype_header().is_value_type(), "sanity");
+
+  // Set up the offset to the members of this klass
+  _adr_value_klass_members = calculate_members_address();
+
+  // Placement install the members
+  new (_adr_value_klass_members) Members();
+
+  // Sanity check construction of the members
+  assert(pack_handler() == nullptr, "pack handler not null");
+}
+
+address ValueKlass::calculate_members_address() const {
+  // The members are placed after all other contents inherited from the InstanceKlass
+  return end_of_instance_klass();
+}
