-void InlineTypeNode::make_scalar_in_safepoint(PhaseIterGVN* igvn, Unique_Node_List& worklist, SafePointNode* sfpt) const {
-  JVMState* jvms = sfpt->jvms();
-  assert(jvms != nullptr, "missing JVMS");
