-bool InlineTypeNode::is_allocated(PhaseGVN* phase) const {
-  if (phase->type(get_is_buffered()) == TypeInt::ONE) {
-    return true;
-  }
-  Node* oop = get_oop();
-  const Type* oop_type = (phase != nullptr) ? phase->type(oop) : oop->bottom_type();
-  return !oop_type->maybe_null();
-}
