-    value = igvn.transform(new URShiftINode(payload, shift_val));
-  }
-
-  if (value_bt == T_INT) {
-    return value;
-  } else if (!is_java_primitive(value_bt)) {
-    assert(UseCompressedOops && payload_bt == T_LONG, "Naturally atomic");
