+// Merges 'this' with 'other' by updating the input PhiNodes added by 'clone_with_phis'
+ValueTypeNode* ValueTypeNode::merge_with(PhaseGVN* gvn, const ValueTypeNode* other, int phi_index, bool transform) {
+  assert(value_klass() == other->value_klass(), "Merging incompatible types");
+
+  // Merge oop inputs
+  PhiNode* phi = get_oop()->as_Phi();
+  phi->set_req(phi_index, other->get_oop());
+  if (transform) {
+    set_oop(*gvn, gvn->transform(phi));
+  }
+
+  // Merge is_buffered inputs
+  phi = get_is_buffered()->as_Phi();
+  phi->set_req(phi_index, other->get_is_buffered());
+  if (transform) {
+    set_req(IsBuffered, gvn->transform(phi));
+  }
+
+  // Merge null_marker inputs
+  Node* null_marker = get_null_marker();
+  if (null_marker->is_Phi()) {
+    phi = null_marker->as_Phi();
+    phi->set_req(phi_index, other->get_null_marker());
+    if (transform) {
+      set_req(NullMarker, gvn->transform(phi));
+    }
+  } else {
+    assert(null_marker->find_int_con(0) == 1, "only with a non null value type");
+  }
+
+  // Merge field values
+  for (uint i = 0; i < field_count(); ++i) {
+    Node* val1 = field_value(i);
+    Node* val2 = other->field_value(i);
+    if (field(i)->is_flat()) {
+      if (val2->is_top()) {
+        // The path where 'other' is used is dying. Therefore, we do not need to process the merge with 'other' further.
+        // The phi inputs of 'this' at 'phi_index' will eventually be removed.
+        break;
+      } else if (val2->is_Phi()) {
+        val2 = gvn->transform(val2);
+      }
+
+      assert(val1->is_ValueType() && val2->is_ValueType(), "must be ValueTypeNode: %s - %s", val1->Name(), val2->Name());
+      val1->as_ValueType()->merge_with(gvn, val2->as_ValueType(), phi_index, transform);
+    } else {
+      assert(val1->is_Phi(), "must be a phi node %s", val1->Name());
+      val1->set_req(phi_index, val2);
+    }
+    if (transform) {
+      set_field_value(i, gvn->transform(val1));
+    }
+  }
+  return this;
+}
+
+// Adds a new merge path to a value type node with phi inputs
+void ValueTypeNode::add_new_path(Node* region) const {
+  assert(has_phi_inputs(region), "must have phi inputs");
+
+  PhiNode* phi = get_oop()->as_Phi();
+  phi->add_req(nullptr);
+  assert(phi->req() == region->req(), "must be same size as region");
+
+  phi = get_is_buffered()->as_Phi();
+  phi->add_req(nullptr);
+  assert(phi->req() == region->req(), "must be same size as region");
+
+  phi = get_null_marker()->as_Phi();
+  phi->add_req(nullptr);
+  assert(phi->req() == region->req(), "must be same size as region");
+
+  for (uint i = 0; i < field_count(); ++i) {
+    Node* val = field_value(i);
+    if (val->is_ValueType()) {
+      val->as_ValueType()->add_new_path(region);
+    } else {
+      val->as_Phi()->add_req(nullptr);
+      assert(val->req() == region->req(), "must be same size as region");
+    }
+  }
+}
+
+Node* ValueTypeNode::field_value(uint index) const {
+  assert(index < field_count(), "index out of bounds");
+  return in(Values + index);
+}
+
+// Get the value of the field at the given offset.
+// If 'recursive' is true, flat value type fields will be resolved recursively.
+Node* ValueTypeNode::field_value_by_offset(int offset, bool recursive) const {
+  // Find the declared field which contains the field we are looking for
+  int index = value_klass()->field_index_by_offset(offset);
+  Node* value = field_value(index);
+  assert(value != nullptr, "field value not found");
+  ciField* field = this->field(index);
+  assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+
+  if (value->is_top()) {
+    // The graph is dying but a load may still ask for a nested field
+    // inside a flattened field before the dead load itself is folded away.
+    assert(offset == field->offset_in_bytes() || field->is_flat(), "offset mismatch");
+    return value;
+  }
+  if (!recursive || !field->is_flat()) {
+    assert(offset == field->offset_in_bytes(), "offset mismatch");
+    return value;
+  }
+
+  // Flat value type field
+  ValueTypeNode* vt = value->as_ValueType();
+  assert(field->is_flat(), "must be flat");
+  if (offset == field->null_marker_offset()) {
+    return vt->get_null_marker();
+  } else {
+    int sub_offset = offset - field->offset_in_bytes(); // Offset of the flattened field inside the declared field
+    sub_offset += vt->value_klass()->payload_offset(); // Add header size
+    return vt->field_value_by_offset(sub_offset, recursive);
+  }
+}
+
+void ValueTypeNode::set_field_value(uint index, Node* value) {
+  assert(index < field_count(), "index out of bounds");
+  set_req(Values + index, value);
+}
+
+void ValueTypeNode::set_field_value_by_offset(int offset, Node* value) {
+  set_field_value(field_index(offset), value);
+}
+
+uint ValueTypeNode::field_index(int offset) const {
+  uint i = 0;
+  for (; i < field_count() && field(i)->offset_in_bytes() != offset; i++) { }
+  assert(i < field_count(), "field not found");
+  return i;
+}
+
+ciField* ValueTypeNode::field(uint index) const {
+  assert(index < field_count(), "index out of bounds");
+  return value_klass()->declared_nonstatic_field_at(index);
+}
+
+uint ValueTypeNode::add_fields_to_safepoint(Unique_Node_List& worklist, SafePointNode* sfpt) const {
+  uint cnt = 0;
+  for (uint i = 0; i < field_count(); ++i) {
+    Node* value = field_value(i);
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    if (field->is_flat()) {
+      ValueTypeNode* vt = value->as_ValueType();
+      cnt += vt->add_fields_to_safepoint(worklist, sfpt);
+      if (!field->is_null_free()) {
+        // The null marker of a flat field is added right after we scalarize that field
+        sfpt->add_req(vt->get_null_marker());
+        cnt++;
+      }
+      continue;
+    }
+    if (value->is_ValueType()) {
+      // Add value type to the worklist to process later
+      worklist.push(value);
+    }
+    sfpt->add_req(value);
+    cnt++;
+  }
+  return cnt;
+}
+
+void ValueTypeNode::make_scalar_in_safepoint(PhaseIterGVN* igvn, Unique_Node_List& worklist, SafePointNode* sfpt) const {
+  JVMState* jvms = sfpt->jvms();
+  assert(jvms != nullptr, "missing JVMS");
+  uint first_ind = (sfpt->req() - jvms->scloff());
+
+  // Iterate over the value type fields in order of increasing offset and add the
+  // field values to the safepoint. Nullable value types have a null marker field that
+  // needs to be checked before using the field values.
+  sfpt->add_req(get_null_marker());
+  uint nfields = add_fields_to_safepoint(worklist, sfpt);
+  jvms->set_endoff(sfpt->req());
+  // Replace safepoint edge by SafePointScalarObjectNode
+  SafePointScalarObjectNode* sobj = new SafePointScalarObjectNode(type()->isa_instptr(),
+                                                                  nullptr,
+                                                                  first_ind,
+                                                                  sfpt->jvms()->depth(),
+                                                                  nfields);
+  sobj->init_req(0, igvn->C->root());
+  sobj = igvn->transform(sobj)->as_SafePointScalarObject();
+  igvn->rehash_node_delayed(sfpt);
+  for (uint i = jvms->debug_start(); i < jvms->debug_end(); i++) {
+    Node* debug = sfpt->in(i);
+    if (debug != nullptr && debug->uncast() == this) {
+      sfpt->set_req(i, sobj);
+    }
+  }
+}
+
+bool ValueTypeNode::make_scalar_in_safepoints(PhaseIterGVN* igvn, bool allow_oop) {
+  return make_scalar_in_safepoints(igvn, allow_oop, nullptr);
+}
+
+bool ValueTypeNode::make_scalar_in_safepoints(PhaseIterGVN* igvn, bool allow_oop, SafePointNode* safepoint) {
+  // If the value type has a constant or loaded oop, use the oop instead of scalarization
+  // in the safepoint to avoid keeping field loads live just for the debug info.
+  Node* oop = get_oop();
+  bool use_oop = false;
+  if (allow_oop && is_allocated(igvn) && oop->is_Phi()) {
+    Unique_Node_List worklist;
+    VectorSet visited;
+    visited.set(oop->_idx);
+    worklist.push(oop);
+    use_oop = true;
+    while (worklist.size() > 0 && use_oop) {
+      Node* n = worklist.pop();
+      for (uint i = 1; i < n->req(); i++) {
+        Node* in = n->in(i);
+        if (in->is_Phi() && !visited.test_set(in->_idx)) {
+          worklist.push(in);
+        } else if (!(in->is_Con() || in->is_Parm())) {
+          use_oop = false;
+          break;
+        }
+      }
+    }
+  } else {
+    use_oop = allow_oop && is_allocated(igvn) &&
+              (oop->is_Con() || oop->is_Parm() || oop->is_Load() || (oop->isa_DecodeN() && oop->in(1)->is_Load()));
+  }
+
+  ResourceMark rm;
+  Unique_Node_List safepoints;
+  if (safepoint == nullptr) {
+    // Gathering all SafePoint users of `this`...
+    Unique_Node_List worklist;
+    worklist.push(this);
+    while (worklist.size() > 0) {
+      Node* n = worklist.pop();
+      for (DUIterator_Fast imax, i = n->fast_outs(imax); i < imax; i++) {
+        Node* use = n->fast_out(i);
+        if (use->is_SafePoint() && !use->is_CallLeaf() && (!use->is_Call() || use->as_Call()->has_debug_use(n))) {
+          safepoints.push(use);
+        } else if (use->is_ConstraintCast()) {
+          worklist.push(use);
+        }
+      }
+    }
+  } else {
+    // ...or just the provided one if given.
+    safepoints.push(safepoint);
+  }
+
+  // Scalarize the value type in all safepoint uses but first check if we
+  // have enough nodes left to create a new SafePointScalarObjectNode per use.
+  Compile* C = igvn->C;
+  if ((C->live_nodes() + safepoints.size() + NodeLimitFudgeFactor) > C->max_node_limit()) {
+    return false;
+  }
+  Unique_Node_List vt_worklist;
+  while (safepoints.size() > 0) {
+    SafePointNode* sfpt = safepoints.pop()->as_SafePoint();
+    if (use_oop) {
+      for (uint i = sfpt->jvms()->debug_start(); i < sfpt->jvms()->debug_end(); i++) {
+        Node* debug = sfpt->in(i);
+        if (debug != nullptr && debug->uncast() == this) {
+          sfpt->set_req(i, get_oop());
+        }
+      }
+      igvn->rehash_node_delayed(sfpt);
+    } else {
+      make_scalar_in_safepoint(igvn, vt_worklist, sfpt);
+    }
+  }
+  // Now scalarize non-flat fields
+  for (uint i = 0; i < vt_worklist.size(); ++i) {
+    ValueTypeNode* vt = vt_worklist.at(i)->isa_ValueType();
+    if (!vt->make_scalar_in_safepoints(igvn)) {
+      return false;
+    }
+  }
+  if (outcnt() == 0) {
+    igvn->record_for_igvn(this);
+  }
+  return true;
+}
+
+void ValueTypeNode::load(GraphKit* kit, Node* base, Node* ptr, bool immutable_memory, bool trust_null_free_oop, DecoratorSet decorators) {
+  // Initialize the value type by loading its field values from
+  // memory and adding the values as input edges to the node.
+  ciValueKlass* vk = value_klass();
+  for (uint i = 0; i < field_count(); ++i) {
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    int field_off = field->offset_in_bytes() - vk->payload_offset();
+    Node* field_ptr = kit->basic_plus_adr(base, ptr, field_off);
+    Node* value = nullptr;
+    ciType* ft = field->type();
+    bool field_null_free = field->is_null_free();
+    if (field->is_flat()) {
+      // Recursively load the flat value type field
+      ciValueKlass* fvk = ft->as_value_klass();
+      bool atomic = field->is_atomic();
+      value = make_from_flat_impl(kit, fvk, base, field_ptr, atomic, immutable_memory,
+                                  field_null_free, trust_null_free_oop && field_null_free, decorators);
+    } else {
+      // Load field value from memory
+      BasicType bt = type2field[ft->basic_type()];
+      assert(is_java_primitive(bt) || field_ptr->bottom_type()->is_ptr_to_narrowoop() == UseCompressedOops, "inconsistent");
+      const Type* val_type = Type::get_const_type(ft);
+      if (trust_null_free_oop && field_null_free) {
+        val_type = val_type->join_speculative(TypePtr::NOTNULL);
+      }
+      const TypePtr* field_ptr_type = (decorators & C2_MISMATCHED) == 0 ? kit->gvn().type(field_ptr)->is_ptr() : TypeRawPtr::BOTTOM;
+      value = kit->access_load_at(base, field_ptr, field_ptr_type, val_type, bt, decorators);
+    }
+    set_field_value(i, value);
+  }
+}
+
+void ValueTypeNode::store_flat(GraphKit* kit, Node* base, Node* ptr, bool atomic, bool immutable_memory, bool null_free, DecoratorSet decorators) {
+  ciValueKlass* vk = value_klass();
+  bool do_atomic = atomic;
+  // With immutable memory, a non-atomic load and an atomic load are the same
+  if (immutable_memory) {
+    do_atomic = false;
+  }
+  // If there is only one flattened field, a non-atomic load and an atomic load are the same
+  if (vk->is_naturally_atomic(null_free)) {
+    do_atomic = false;
+  }
+
+  if (!do_atomic) {
+    if (!null_free) {
+      int nm_offset = vk->null_marker_offset_in_payload();
+      Node* nm_ptr = kit->basic_plus_adr(base, ptr, nm_offset);
+      const TypePtr* nm_ptr_type = (decorators & C2_MISMATCHED) == 0 ? kit->gvn().type(nm_ptr)->is_ptr() : TypeRawPtr::BOTTOM;
+      kit->access_store_at(base, nm_ptr, nm_ptr_type, get_null_marker(), TypeInt::BOOL, T_BOOLEAN, decorators);
+    }
+    store(kit, base, ptr, immutable_memory, decorators);
+    return;
+  }
+
+  StoreFlatNode::store(kit, base, ptr, this, null_free, decorators);
+}
+
+void ValueTypeNode::store_flat_array(GraphKit* kit, Node* base, Node* idx) {
+  PhaseGVN& gvn = kit->gvn();
+  DecoratorSet decorators = IN_HEAP | IS_ARRAY | MO_UNORDERED;
+  kit->C->set_flat_accesses();
+  ciValueKlass* vk = value_klass();
+  assert(vk->maybe_flat_in_array(), "element type %s cannot be flat in array", vk->name()->as_utf8());
+
+  RegionNode* region = new RegionNode(4);
+  gvn.set_type(region, Type::CONTROL);
+  kit->record_for_igvn(region);
+
+  Node* input_memory_state = kit->reset_memory();
+  kit->set_all_memory(input_memory_state);
+
+  PhiNode* mem = PhiNode::make(region, input_memory_state, Type::MEMORY, TypePtr::BOTTOM);
+  gvn.set_type(mem, Type::MEMORY);
+  kit->record_for_igvn(mem);
+
+  PhiNode* io = PhiNode::make(region, kit->i_o(), Type::ABIO);
+  gvn.set_type(io, Type::ABIO);
+  kit->record_for_igvn(io);
+
+  Node* bol_null_free = kit->null_free_array_test(base); // Argument evaluation order is undefined in C++ and since this sets control, it needs to come first
+  IfNode* iff_null_free = kit->create_and_map_if(kit->control(), bol_null_free, PROB_FAIR, COUNT_UNKNOWN);
+
+  // Nullable
+  kit->set_control(kit->IfFalse(iff_null_free));
+  if (!kit->stopped()) {
+    assert(vk->has_nullable_atomic_layout(), "element type %s does not have a nullable flat layout", vk->name()->as_utf8());
+    kit->set_all_memory(input_memory_state);
+    Node* cast = kit->cast_to_flat_array_exact(base, vk, false, true);
+    Node* ptr = kit->array_element_address(cast, idx, T_FLAT_ELEMENT);
+    store_flat(kit, cast, ptr, true, false, false, decorators);
+
+    region->init_req(1, kit->control());
+    mem->set_req(1, kit->reset_memory());
+    io->set_req(1, kit->i_o());
+  }
+
+  // Null-free
+  kit->set_control(kit->IfTrue(iff_null_free));
+  if (!kit->stopped()) {
+    kit->set_all_memory(input_memory_state);
+
+    Node* bol_atomic = kit->null_free_atomic_array_test(base, vk);
+    IfNode* iff_atomic = kit->create_and_map_if(kit->control(), bol_atomic, PROB_FAIR, COUNT_UNKNOWN);
+
+    // Atomic
+    kit->set_control(kit->IfTrue(iff_atomic));
+    if (!kit->stopped()) {
+      assert(vk->has_null_free_atomic_layout(), "element type %s does not have a null-free atomic flat layout", vk->name()->as_utf8());
+      kit->set_all_memory(input_memory_state);
+      Node* cast = kit->cast_to_flat_array_exact(base, vk, true, true);
+      Node* ptr = kit->array_element_address(cast, idx, T_FLAT_ELEMENT);
+      store_flat(kit, cast, ptr, true, false, true, decorators);
+
+      region->init_req(2, kit->control());
+      mem->set_req(2, kit->reset_memory());
+      io->set_req(2, kit->i_o());
+    }
+
+    // Non-atomic
+    kit->set_control(kit->IfFalse(iff_atomic));
+    if (!kit->stopped()) {
+      assert(vk->has_null_free_non_atomic_layout(), "element type %s does not have a null-free non-atomic flat layout", vk->name()->as_utf8());
+      kit->set_all_memory(input_memory_state);
+      Node* cast = kit->cast_to_flat_array_exact(base, vk, true, false);
+      Node* ptr = kit->array_element_address(cast, idx, T_FLAT_ELEMENT);
+      store_flat(kit, cast, ptr, false, false, true, decorators);
+
+      region->init_req(3, kit->control());
+      mem->set_req(3, kit->reset_memory());
+      io->set_req(3, kit->i_o());
+    }
+  }
+
+  kit->set_control(gvn.transform(region));
+  kit->set_all_memory(gvn.transform(mem));
+  kit->set_i_o(gvn.transform(io));
+}
+
+void ValueTypeNode::store(GraphKit* kit, Node* base, Node* ptr, bool immutable_memory, DecoratorSet decorators) const {
+  // Write field values to memory
+  ciValueKlass* vk = value_klass();
+  for (uint i = 0; i < field_count(); ++i) {
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    int field_off = field->offset_in_bytes() - vk->payload_offset();
+    Node* field_val = field_value(i);
+    bool field_null_free = field->is_null_free();
+    ciType* ft = field->type();
+    Node* field_ptr = kit->basic_plus_adr(base, ptr, field_off);
+    if (field->is_flat()) {
+      // Recursively store the flat value type field
+      bool atomic = field->is_atomic();
+      field_val->as_ValueType()->store_flat(kit, base, field_ptr, atomic, immutable_memory, field_null_free, decorators);
+    } else {
+      // Store field value to memory
+      BasicType bt = type2field[ft->basic_type()];
+      const TypePtr* field_ptr_type = (decorators & C2_MISMATCHED) == 0 ? kit->gvn().type(field_ptr)->is_ptr() : TypeRawPtr::BOTTOM;
+      const Type* val_type = Type::get_const_type(ft);
+      kit->access_store_at(base, field_ptr, field_ptr_type, field_val, val_type, bt, decorators);
+    }
+  }
+}
+
+// If a value class contains cycle, bail out from trying to expand substitutability check involving it
+static bool check_cycle(ciValueKlass* vk) {
+  ResourceMark rm;
+  GrowableArray<Pair<ciValueKlass*, int>> visited;
+  visited.push(Pair(vk, 0));
+  while (visited.is_nonempty()) {
+    ciValueKlass* current = visited.top().first;
+    bool finish = true;
+    for (int field_idx = visited.top().second; field_idx < current->nof_nonstatic_fields(); field_idx++) {
+      ciField* field = current->nonstatic_field_at(field_idx);
+      ciType* ft = field->type();
+      if (!ft->is_value_klass()) {
+        continue;
+      } else if (visited.find_if([&](const auto& entry) { return entry.first == ft; }) >= 0) {
+        return true;
+      } else {
+        visited.top().second = field_idx + 1;
+        visited.push(Pair(ft->as_value_klass(), 0));
+        finish = false;
+        break;
+      }
+    }
+    if (finish) {
+      visited.pop();
+    }
+  }
+  return false;
+}
+
+// Check if 'lhs' and 'rhs' are the same oop, possibly wrapped in an ValueTypeNode.
+static bool same_oop(PhaseGVN* phase, Node* lhs, Node* rhs) {
+  ValueTypeNode* lhs_inline = lhs->isa_ValueType();
+  if (lhs_inline != nullptr && lhs_inline->is_allocated(phase)) {
+    lhs = lhs_inline->get_oop();
+  }
+  ValueTypeNode* rhs_inline = rhs->isa_ValueType();
+  if (rhs_inline != nullptr && rhs_inline->is_allocated(phase)) {
+    rhs = rhs_inline->get_oop();
+  }
+  return lhs->eqv_uncast(rhs);
+}
+
+// Check if a substitutability check between 'lhs' and 'rhs' can be implemented in IR
+bool ValueTypeNode::can_emit_substitutability_check(PhaseGVN* phase, Node* lhs, Node* rhs) {
+  // We can't create new ValueTypeNodes after macro expansion
+  if (!phase->C->allow_macro_nodes()) {
+    return false;
+  }
+
+  if (!lhs->bottom_type()->isa_ptr() ||
+      (rhs != nullptr && !rhs->bottom_type()->isa_ptr())) {
+    return false;
+  }
+
+  if (rhs != nullptr && same_oop(phase, lhs, rhs)) {
+    return true;
+  }
+
+  if (!lhs->bottom_type()->is_ptr()->can_be_value_type() ||
+      (rhs != nullptr && !rhs->bottom_type()->is_ptr()->can_be_value_type())) {
+    return true;
+  }
+
+  if (!lhs->is_ValueType() && (rhs == nullptr || !rhs->is_ValueType())) {
+    return false;
+  }
+
+  if (!lhs->is_ValueType()) {
+    swap(lhs, rhs);
+  }
+
+  ValueTypeNode* lhs_inline = lhs->as_ValueType();
+  ValueTypeNode* rhs_inline = rhs != nullptr ? rhs->isa_ValueType() : nullptr;
+  if (rhs_inline != nullptr && lhs_inline->type()->value_klass() != rhs_inline->type()->value_klass()) {
+    // Dead code, can skip the substitutability check
+    return true;
+  }
+
+  if (check_cycle(lhs_inline->value_klass())) {
+    return false;
+  }
+
+  for (uint i = 0; i < lhs_inline->field_count(); i++) {
+    ciType* ft = lhs_inline->field(i)->type();
+    if (!ft->can_be_value_klass()) {
+      continue;
+    }
+
+    Node* lhs_fv = lhs_inline->field_value(i);
+    Node* rhs_fv = rhs_inline != nullptr ? rhs_inline->field_value(i) : nullptr;
+    if (!can_emit_substitutability_check(phase, lhs_fv, rhs_fv)) {
+      return false;
+    }
+  }
+  return true;
+}
+
+// Compare lhs and rhs given they are not value objects
+static void emit_substitutability_check_primitive(GraphKit* kit, PhiNode* result, Node* lhs, Node* rhs, BasicType bt) {
+  PhaseGVN& gvn = kit->gvn();
+  Node* cmp;
+  if (bt == T_INT || is_subword_type(bt)) {
+    cmp = kit->CmpI(lhs, rhs);
+  } else if (bt == T_LONG) {
+    cmp = kit->CmpL(lhs, rhs);
+  } else if (bt == T_FLOAT) {
+    lhs = gvn.transform(new MoveF2INode(lhs));
+    rhs = gvn.transform(new MoveF2INode(rhs));
+    cmp = kit->CmpI(lhs, rhs);
+  } else if (bt == T_DOUBLE) {
+    lhs = gvn.transform(new MoveD2LNode(lhs));
+    rhs = gvn.transform(new MoveD2LNode(rhs));
+    cmp = kit->CmpL(lhs, rhs);
+  } else {
+    assert(is_reference_type(bt), "unexpected bt %s", type2name(bt));
+    cmp = kit->CmpP(lhs, rhs);
+  }
+
+  Node* bol = kit->Bool(cmp, BoolTest::eq);
+  IfNode* iff = kit->create_and_map_if(kit->control(), bol, PROB_FAIR, COUNT_UNKNOWN);
+
+  Node* iff_false = kit->IfFalse(iff);
+  result->add_req(kit->intcon(0));
+  result->region()->add_req(iff_false);
+
+  Node* iff_true = kit->IfTrue(iff);
+  kit->set_control(iff_true);
+}
+
+// Try to see what should be done with lhs and rhs. Either we can emit the answer if it is simple,
+// give up and emit a call to runtime, or start comparing the value objects field-by-field. In the
+// last case, NodeSentinel is returned.
+static Node* emit_substitutability_check_pointer(GraphKit* kit, PhiNode* result, Node* lhs, Node* rhs) {
+  PhaseGVN& gvn = kit->gvn();
+  Node* top = kit->C->top();
+  const Type* lhs_type = gvn.type(lhs);
+  const Type* rhs_type = gvn.type(rhs);
+
+  // Dead graph
+  if (lhs_type == Type::TOP || rhs_type == Type::TOP) {
+    kit->set_control(top);
+    return top;
+  }
+
+  Node* cmp = nullptr;
+  if (same_oop(&gvn, lhs, rhs)) {
+    cmp = kit->intcon(0);
+  } else if (!lhs_type->is_ptr()->can_be_value_type() || !rhs_type->is_ptr()->can_be_value_type()) {
+    // If one of the sides is not a value object, can only be substitutable if they are the same
+    cmp = kit->CmpP(lhs, rhs);
+  } else if (lhs_type->is_instptr()->as_klass_type()->join(rhs_type->is_instptr()->as_klass_type())->empty()) {
+    // Both belongs to provably different types, must be different unless both are null. Cannot
+    // rely on the pointer independence alone because different pointers may still be
+    // substitutable.
+    cmp = kit->CmpP(lhs, rhs);
+  }
+  if (cmp != nullptr) {
+    Node* res = kit->Bool(cmp, BoolTest::eq);
+    IfNode* iff = kit->create_and_map_if(kit->control(), res, PROB_FAIR, COUNT_UNKNOWN);
+
+    Node* iff_false = kit->IfFalse(iff);
+    result->region()->add_req(iff_false);
+    result->add_req(gvn.intcon(0));
+
+    Node* iff_true = kit->IfTrue(iff);
+    kit->set_control(iff_true);
+    return iff_true;
+  }
+
+  if (!lhs_type->is_valueklassptr() && !rhs_type->is_valueklassptr()) {
+    return nullptr;
+  }
+
+  // A cycle, give up
+  ciValueKlass* vk = lhs_type->is_valueklassptr() ? lhs_type->value_klass() : rhs_type->value_klass();
+  if (check_cycle(vk)) {
+    return nullptr;
+  }
+
+  return NodeSentinel;
+}
+
+Node* ValueTypeNode::emit_substitutability_check(GraphKit* kit, Node* lhs, Node* rhs) {
+  if (!kit->C->allow_macro_nodes()) {
+    // After macro expansion, ValueTypeNodes are also eliminated, creation of new ones then is not
+    // allowed
+    return nullptr;
+  }
+
+  PhaseIterGVN& igvn = *kit->gvn().is_IterGVN();
+  RegionNode* region = new RegionNode(1);
+  PhiNode* result = new PhiNode(region, TypeInt::BOOL);
+  igvn.register_new_node_with_optimizer(region);
+  igvn.register_new_node_with_optimizer(result);
+
+  Node* preprocess = emit_substitutability_check_pointer(kit, result, lhs, rhs);
+  if (preprocess == nullptr) {
+    return nullptr;
+  } else if (preprocess != NodeSentinel) {
+    region->add_req(kit->control());
+    result->add_req(igvn.intcon(1));
+    kit->set_control(region);
+    return result;
+  }
+
+  const Type* lhs_type = igvn.type(lhs);
+  const Type* rhs_type = igvn.type(rhs);
+  assert(!lhs_type->maybe_null() && !rhs_type->maybe_null(), "must check null beforehand");
+  ciValueKlass* vk = lhs_type->is_valueklassptr() ? lhs_type->value_klass() : rhs_type->value_klass();
+  const TypeInstPtr* vk_type = TypeOopPtr::make_from_klass(vk)->join(TypePtr::NOTNULL)->is_instptr();
+
+  if (!lhs->is_ValueType()) {
+    if (!lhs_type->higher_equal(vk_type)) {
+      lhs = igvn.transform(new CheckCastPPNode(kit->control(), lhs, vk_type, ConstraintCastNode::DependencyType::NonFloatingNarrowing));
+    }
+    lhs = ValueTypeNode::make_from_oop(kit, lhs, vk);
+  }
+  if (!rhs->is_ValueType()) {
+    if (!rhs_type->higher_equal(vk_type)) {
+      rhs = igvn.transform(new CheckCastPPNode(kit->control(), rhs, vk_type, ConstraintCastNode::DependencyType::NonFloatingNarrowing));
+    }
+    rhs = ValueTypeNode::make_from_oop(kit, rhs, vk);
+  }
+
+  RegionNode* true_region = new RegionNode(3);
+  igvn.register_new_node_with_optimizer(true_region);
+  region->add_req(true_region);
+  result->add_req(igvn.intcon(1));
+
+  // To verify the substitutability of 2 notnull value objects of the same type, we need to check
+  // the substitutability of each field in the objects:
+  //
+  // substitutable(cur_lhs, cur_rhs) {
+  //   cur_start_region:
+  //
+  //   if (cur_lhs.field1 == null && cur_rhs.field1 == null) {
+  //     goto cur_true_field1_region;
+  //   } else if ((cur_lhs.field1 == null) != (cur_rhs.field1 == null) {
+  //     return false;
+  //   } else if (cur_lhs.field1.klass != cur_rhs.field1.klass) {
+  //     return false;
+  //   }
+  //
+  //   cur_start_field1_region:
+  //   if (substitutable(cur_lhs.field1, cur_rhs.field1)) {
+  //     return false;
+  //   }
+  //   cur_true_field1_region:
+  //
+  //   if (cur_lhs.field2 == null && cur_rhs.field2 == null) {
+  //     goto cur_true_field2_region;
+  //   } else if ((cur_lhs.field2 == null) != (cur_rhs.field2 == null) {
+  //     return false;
+  //   } else if (cur_lhs.field2.klass != cur_rhs.field2.klass) {
+  //     return false;
+  //   }
+  //
+  //   cur_start_field2_region:
+  //   if (!substitutable(cur_lhs.field1, cur_rhs.field1)) {
+  //     return false;
+  //   }
+  //   cur_true_field2_region:
+  //
+  //   ...
+  //
+  //   cur_true_fieldn_region:
+  //
+  //   cur_true_region:
+  // }
+  //
+  // To avoid recursion, for field values that are value objects, we create the start and end
+  // region for the substitutability check of that field when both sides are notnull, save them on
+  // the worklist to process them later.
+  ResourceMark rm;
+  using WorklistEntry = Tuple<Node*, RegionNode*, ValueTypeNode*, ValueTypeNode*>;
+  GrowableArray<WorklistEntry> worklist;
+  worklist.push(WorklistEntry(kit->control(), true_region, lhs->as_ValueType(), rhs->as_ValueType()));
+  while (worklist.is_nonempty()) {
+    WorklistEntry entry = worklist.pop();
+    Node* cur_start_region = entry.get<0>();
+    RegionNode* cur_true_region = entry.get<1>();
+    ValueTypeNode* cur_lhs = entry.get<2>();
+    ValueTypeNode* cur_rhs = entry.get<3>();
+
+    kit->set_control(cur_start_region);
+    if (kit->stopped()) {
+      break;
+    }
+    ciValueKlass* vk = cur_lhs->value_klass();
+    assert(vk == cur_rhs->value_klass(), "should not reach here otherwise");
+
+    auto is_simple_field = [](ciField* field) {
+      ciType* ft = field->type();
+      return is_java_primitive(ft->basic_type()) || !ft->as_klass()->can_be_value_klass();
+    };
+
+    // Go through all fields, process the simple ones first
+    for (int field_idx = 0; field_idx < vk->nof_declared_nonstatic_fields(); field_idx++) {
+      ciField* field = vk->declared_nonstatic_field_at(field_idx);
+      if (is_simple_field(field)) {
+        Node* cur_lhs_field = cur_lhs->field_value(field_idx);
+        Node* cur_rhs_field = cur_rhs->field_value(field_idx);
+        emit_substitutability_check_primitive(kit, result, cur_lhs_field, cur_rhs_field, field->type()->basic_type());
+      }
+    }
+
+    for (int field_idx = 0; field_idx < vk->nof_declared_nonstatic_fields(); field_idx++) {
+      ciField* field = vk->declared_nonstatic_field_at(field_idx);
+      if (is_simple_field(field)) {
+        // These fields have already been processed
+        continue;
+      }
+
+      Node* cur_lhs_field = cur_lhs->field_value(field_idx);
+      Node* cur_rhs_field = cur_rhs->field_value(field_idx);
+      ValueTypeNode* cur_lhs_inline = cur_lhs_field->isa_ValueType();
+      ValueTypeNode* cur_rhs_inline = cur_rhs_field->isa_ValueType();
+
+      Node* preprocess = emit_substitutability_check_pointer(kit, result, cur_lhs_field, cur_rhs_field);
+      if (kit->stopped()) {
+        break;
+      } else if (preprocess == nullptr) {
+        // Must emit a substitutability check for this field, give up for now
+        return nullptr;
+      } else if (preprocess != NodeSentinel) {
+        continue;
+      }
+
+      // When field is not null-free, the shape would look like this:
+      //
+      // current_control:
+      // if (cur_lhs_field == null) {
+      //   if (cur_rhs_field == null) {
+      //     goto field_true_region;
+      //   } else {
+      //     return false;
+      //   }
+      // } else {
+      //   if (cur_rhs_field == null) {
+      //     return false;
+      //   }
+      // }
+      // if (cur_lhs_field.klass != cur_rhs_field.klass) {
+      //   return false;
+      // }
+      //
+      // field_start_region:
+      // if (!substitutable(cur_lhs_field, cur_rhs_field)) {
+      //   return false;
+      // }
+      // field_true_region:
+      //
+      // The substitutability test between the fields of cur_lhs_field and cur_rhs_field is then
+      // pushed on the worklist to be expanded later.
+      RegionNode* field_true_region = new RegionNode(3);
+      igvn.register_new_node_with_optimizer(field_true_region);
+
+      // Firstly, filter the cases when either is null
+      Node* null_unknown = kit->top();
+      cur_lhs_field = kit->null_check_common(cur_lhs_field, T_OBJECT, false, &null_unknown);
+      if (!null_unknown->is_top()) {
+        PreserveJVMState pjvms(kit);
+        kit->set_control(null_unknown);
+        Node* null_null = kit->top();
+        kit->null_check_common(cur_rhs_field, T_OBJECT, false, &null_null);
+
+        // null - null, skip other checks
+        field_true_region->init_req(1, null_null);
+
+        // null - notnull
+        if (!kit->stopped()) {
+          region->add_req(kit->control());
+          result->add_req(igvn.intcon(0));
+        }
+      }
+      if (kit->stopped()) {
+        // cur_lhs_field is always null
+        kit->set_control(field_true_region);
+        continue;
+      }
+
+      Node* notnull_null = kit->top();
+      cur_rhs_field = kit->null_check_common(cur_rhs_field, T_OBJECT, false, &notnull_null);
+      if (!notnull_null->is_top()) {
+        region->add_req(notnull_null);
+        result->add_req(igvn.intcon(0));
+      }
+
+      if (kit->stopped()) {
+        // cur_rhs_field is always null
+        kit->set_control(field_true_region);
+        continue;
+      }
+      assert(!igvn.type(cur_lhs_field)->maybe_null() && !igvn.type(cur_rhs_field)->maybe_null(), "must be notnull");
+
+      // Can expand this comparison
+      const Type* cur_lhs_field_type = igvn.type(cur_lhs_field);
+      const Type* cur_rhs_field_type = igvn.type(cur_rhs_field);
+      ciValueKlass* vk = cur_lhs_field_type->is_valueklassptr() ? cur_lhs_field_type->value_klass() : cur_rhs_field_type->value_klass();
+      const TypeInstKlassPtr* vk_klass_type = TypeInstKlassPtr::make(vk, Type::ignore_interfaces);
+      Node* vk_klass = igvn.makecon(vk_klass_type);
+
+      // Both must be vk
+      // ValueTypeNodes need no (new) field loads, so we can use the uncasted value below.
+      if (cur_lhs_inline != nullptr && cur_lhs_inline->value_klass() == vk) {
+        cur_lhs_field = cur_lhs_inline;
+      } else {
+        Node* not_vk = kit->top();
+        cur_lhs_field = kit->gen_checkcast(cur_lhs_field, vk_klass, &not_vk);
+        if (!not_vk->is_top()) {
+          region->add_req(not_vk);
+          result->add_req(igvn.intcon(0));
+        }
+        cur_lhs_field = ValueTypeNode::make_from_oop(kit, cur_lhs_field, vk);
+      }
+
+      if (cur_rhs_inline != nullptr && cur_rhs_inline->value_klass() == vk) {
+        cur_rhs_field = cur_rhs_inline;
+      } else {
+        Node* not_vk = kit->top();
+        cur_rhs_field = kit->gen_checkcast(cur_rhs_field, vk_klass, &not_vk);
+        if (!not_vk->is_top()) {
+          region->add_req(not_vk);
+          result->add_req(igvn.intcon(0));
+        }
+        cur_rhs_field = ValueTypeNode::make_from_oop(kit, cur_rhs_field, vk);
+      }
+
+      if (!kit->stopped()) {
+        // Push the expanded ValueTypeNodes for processing later
+        worklist.push(WorklistEntry(kit->control(), field_true_region, cur_lhs_field->as_ValueType(), cur_rhs_field->as_ValueType()));
+      }
+
+      kit->set_control(field_true_region);
+    }
+
+    cur_true_region->init_req(2, kit->control());
+    kit->set_control(cur_true_region);
+  }
+
+  kit->set_control(region);
+  return result;
+}
+
+// Check if identityHashCode of 'arg' can be implemented in IR.
+// Set klass_hash to be used as the seed of the hash. It might not be available later,
+// and we want emit_identity_hash_code not to fail on that.
+bool ValueTypeNode::can_emit_identity_hash_code(const PhaseIterGVN& igvn, Node* arg, intptr_t& klass_hash) {
+  const Type* arg_type = igvn.type(arg);
+  if (arg_type == TypePtr::NULL_PTR) {
+    return true;
+  }
+  if (!arg_type->is_valueklassptr()) {
+    return false;
+  }
+  ciValueKlass* vk = arg_type->value_klass();
+  if (vk->number_of_oop_entries_in_acmp_map() > 0) {
+    return false;
+  }
+  klass_hash = vk->java_mirror()->hash();
+  if (klass_hash == markWord::no_hash) {
+    return false;
+  }
+  return true;
+}
+
+Node* ValueTypeNode::emit_identity_hash_code(GraphKit* kit, Node* arg, intptr_t klass_hash) {
+  if (!kit->C->allow_macro_nodes()) {
+    // After macro expansion, ValueTypeNodes are also eliminated, creation of new ones then is not
+    // allowed
+    return nullptr;
+  }
+  PhaseIterGVN& igvn = *kit->gvn().is_IterGVN();
+
+  RegionNode* region = new RegionNode(1);
+  PhiNode* phi_result = new PhiNode(region, TypeInt::INT);
+  igvn.register_new_node_with_optimizer(region);
+  igvn.register_new_node_with_optimizer(phi_result);
+
+  Node* null_ctl = kit->top();
+  arg = kit->null_check_oop(arg, &null_ctl, false, false, false);
+  if (!null_ctl->is_top()) {
+    region->add_req(null_ctl);
+    phi_result->add_req(kit->intcon(0));
+  }
+  const Type* arg_type = igvn.type(arg);
+  if (arg_type->empty()) {
+    kit->set_control(region);
+    return phi_result;
+  }
+
+  assert(arg_type->is_valueklassptr(), "should be a value object at this point");
+  assert(!arg_type->maybe_null(), "must check null beforehand");
+  ciValueKlass* vk = arg_type->value_klass();
+  int number_of_nonoop_entries = vk->number_of_nonoop_entries_in_acmp_map();
+  assert(vk->number_of_oop_entries_in_acmp_map() == 0, "cannot have oops here");
+
+  auto make_load = [&](int offset, const Type* type, BasicType bt) -> Node* {
+    Node* adr = kit->basic_plus_adr(arg, offset);
+    ciField* field = vk->get_field_by_offset(offset, false);
+    // If the load is by chance not a mismatch, let's mark it so. This way, loading the field can be simplified
+    bool is_mismatch = field == nullptr || field->type()->basic_type() != bt;
+    if (bt == T_BYTE && field != nullptr && field->type()->basic_type() == T_BOOLEAN) {
+      is_mismatch = false;
+      bt = T_BOOLEAN;
+      type = TypeInt::BOOL;
+    }
+    return kit->make_load(kit->control(), adr, type, bt, MemNode::unordered, LoadNode::DependsOnlyOnTest, false, false, is_mismatch, is_mismatch);
+  };
+
+  Node* const thirty_one = kit->intcon(31);
+  Node* result = kit->intcon(checked_cast<jint>(klass_hash));
+  for (int i = 0; i < number_of_nonoop_entries; i++) {
+    AcmpMapSegment segment = vk->get_nonoop_segment_of_acmp_map(i);
+    int offset = segment._offset;
+    int size = segment._size;
+    int nlong = size / 8;
+    for (int j = 0; j < nlong; j++) {
+      Node* la = make_load(offset, TypeLong::LONG, T_LONG);
+      result = kit->AddI(kit->MulI(thirty_one, result), kit->ConvL2I(la));
+      result = kit->AddI(kit->MulI(thirty_one, result), kit->ConvL2I(kit->URShiftL(la, kit->intcon(32))));
+      offset += 8;
+    }
+    size -= nlong * 8;
+    int nint = size / 4;
+    for (int j = 0; j < nint; j++) {
+      Node* ia = make_load(offset, TypeInt::INT, T_INT);
+      result = kit->AddI(kit->MulI(thirty_one, result), ia);
+      offset += 4;
+    }
+    size -= nint * 4;
+    int nshort = size / 2;
+    for (int j = 0; j < nshort; j++) {
+      Node* sa = make_load(offset, TypeInt::SHORT, T_SHORT);
+      result = kit->AddI(kit->MulI(thirty_one, result), sa);
+      offset += 2;
+    }
+    size -= nshort * 2;
+    for (int j = 0; j < size; j++) {
+      Node* ba = make_load(offset, TypeInt::BYTE, T_BYTE);
+      result = kit->AddI(kit->MulI(thirty_one, result), ba);
+      offset++;
+    }
+  }
+  result = kit->AndI(result, kit->intcon(markWord::hash_mask));
+
+  region->add_req(kit->control());
+  phi_result->add_req(result);
+
+  kit->set_control(region);
+  return phi_result;
+}
+
+ValueTypeNode* ValueTypeNode::buffer(GraphKit* kit, bool safe_for_replace) {
+  if (is_allocated(&kit->gvn())) {
+    // Already buffered
+    return this;
+  }
+
+  // Check if value type is already buffered
+  Node* not_buffered_ctl = kit->top();
+  Node* not_null_oop = kit->null_check_oop(get_oop(), &not_buffered_ctl, /* never_see_null = */ false, safe_for_replace);
+  if (not_buffered_ctl->is_top()) {
+    // Already buffered
+    ValueTypeNode* vt = clone_if_required(&kit->gvn(), kit->map(), safe_for_replace);
+    vt->set_is_buffered(kit->gvn());
+    vt = kit->gvn().transform(vt)->as_ValueType();
+    if (safe_for_replace) {
+      kit->replace_in_map(this, vt);
+    }
+    return vt;
+  }
+  Node* buffered_ctl = kit->control();
+  kit->set_control(not_buffered_ctl);
+
+  // Value type is not buffered, check if it is null.
+  Node* null_ctl = kit->top();
+  kit->null_check_common(get_null_marker(), T_INT, false, &null_ctl);
+  bool null_free = null_ctl->is_top();
+
+  RegionNode* region = new RegionNode(4);
+  PhiNode* oop = PhiNode::make(region, not_null_oop, type()->join_speculative(null_free ? TypePtr::NOTNULL : TypePtr::BOTTOM));
+
+  // ValueType is already buffered
+  region->init_req(1, buffered_ctl);
+  oop->init_req(1, not_null_oop);
+
+  // ValueType is null
+  region->init_req(2, null_ctl);
+  oop->init_req(2, kit->gvn().zerocon(T_OBJECT));
+
+  PhiNode* io  = PhiNode::make(region, kit->i_o(), Type::ABIO);
+  PhiNode* mem = PhiNode::make(region, kit->merged_memory(), Type::MEMORY, TypePtr::BOTTOM);
+
+  if (!kit->stopped()) {
+    assert(!is_allocated(&kit->gvn()), "already buffered");
+    PreserveJVMState pjvms(kit);
+    ciValueKlass* vk = value_klass();
+    // Allocate and initialize buffer, re-execute on deoptimization.
+    kit->jvms()->set_bci(kit->bci());
+    kit->jvms()->set_should_reexecute(true);
+    kit->kill_dead_locals();
+    Node* klass_node = kit->makecon(TypeKlassPtr::make(vk));
+    Node* alloc_oop  = kit->new_instance(klass_node, nullptr, nullptr, /* deoptimize_on_exception */ true, this);
+    Node* payload_alloc_oop = kit->basic_plus_adr(alloc_oop, vk->payload_offset());
+    store(kit, alloc_oop, payload_alloc_oop, true, IN_HEAP | MO_UNORDERED | C2_TIGHTLY_COUPLED_ALLOC);
+
+    // Do not let stores that initialize this buffer be reordered with a subsequent
+    // store that would make this buffer accessible by other threads.
+    AllocateNode* alloc = AllocateNode::Ideal_allocation(alloc_oop);
+    assert(alloc != nullptr, "must have an allocation node");
+    kit->insert_mem_bar(Op_MemBarStoreStore, alloc->proj_out_or_null(AllocateNode::RawAddress));
+    oop->init_req(3, alloc_oop);
+    region->init_req(3, kit->control());
+    io    ->init_req(3, kit->i_o());
+    mem   ->init_req(3, kit->merged_memory());
+  }
+
+  // Update GraphKit
+  kit->set_control(kit->gvn().transform(region));
+  kit->set_i_o(kit->gvn().transform(io));
+  kit->set_all_memory(kit->gvn().transform(mem));
+  kit->record_for_igvn(region);
+  kit->record_for_igvn(oop);
+  kit->record_for_igvn(io);
+  kit->record_for_igvn(mem);
+
+  // Use cloned ValueTypeNode to propagate oop from now on
+  Node* res_oop = kit->gvn().transform(oop);
+  ValueTypeNode* vt = clone_if_required(&kit->gvn(), kit->map(), safe_for_replace);
+  vt->set_oop(kit->gvn(), res_oop);
+  vt->set_is_buffered(kit->gvn());
+  vt = kit->gvn().transform(vt)->as_ValueType();
+  kit->record_for_igvn(vt);
+  if (safe_for_replace) {
+    kit->replace_in_map(this, vt);
+  }
+  // ValueTypeNode::remove_redundant_allocations piggybacks on split if.
+  // Make sure it gets a chance to remove this allocation.
+  kit->C->set_has_split_ifs(true);
+  return vt;
+}
+
+bool ValueTypeNode::is_allocated(PhaseGVN* phase) const {
+  if (phase->type(get_is_buffered()) == TypeInt::ONE) {
+    return true;
+  }
+  Node* oop = get_oop();
+  const Type* oop_type = (phase != nullptr) ? phase->type(oop) : oop->bottom_type();
+  return !oop_type->maybe_null();
+}
+
+static void replace_proj(Compile* C, CallNode* call, uint& proj_idx, Node* value, BasicType bt) {
+  ProjNode* pn = call->proj_out_or_null(proj_idx);
+  if (pn != nullptr) {
+    if (pn->outcnt() > 0) {
+      PhaseGVN* gvn = C->initial_gvn();
+      const Type* result_type = gvn->type(pn);
+      value = gvn->transform(new OpaqueParseNode(C, value, result_type));
+    }
+    C->gvn_replace_by(pn, value);
+    C->initial_gvn()->hash_delete(pn);
+    pn->set_req(0, C->top());
+  }
+  proj_idx += type2size[bt];
+}
+
+// When a call returns multiple values, it has several result
+// projections, one per field. Replacing the result of the call by an
+// value type node (after late inlining) requires that for each result
+// projection, we find the corresponding value type field.
+void ValueTypeNode::replace_call_results(GraphKit* kit, CallNode* call, Compile* C) const {
+  uint proj_idx = TypeFunc::Parms;
+  // Replace oop projection
+  replace_proj(C, call, proj_idx, get_oop(), T_OBJECT);
+  // Replace field projections
+  replace_field_projs(C, call, proj_idx);
+  // Replace null_marker projection
+  replace_proj(C, call, proj_idx, get_null_marker(), T_BOOLEAN);
+  assert(proj_idx == call->tf()->range_cc()->cnt(), "missed a projection");
+}
+
+void ValueTypeNode::replace_field_projs(Compile* C, CallNode* call, uint& proj_idx) const {
+  for (uint i = 0; i < field_count(); ++i) {
+    Node* value = field_value(i);
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    if (field->is_flat()) {
+      ValueTypeNode* vt = value->as_ValueType();
+      // Replace field projections for flat field
+      vt->replace_field_projs(C, call, proj_idx);
+      if (!field->is_null_free()) {
+        // Replace null_marker projection for nullable field
+        replace_proj(C, call, proj_idx, vt->get_null_marker(), T_BOOLEAN);
+      }
+      continue;
+    }
+    // Replace projection for field value
+    replace_proj(C, call, proj_idx, value, field->type()->basic_type());
+  }
+}
+
+ValueTypeNode* ValueTypeNode::allocate_fields(GraphKit* kit) {
+  ValueTypeNode* vt = clone_if_required(&kit->gvn(), kit->map());
+  for (uint i = 0; i < field_count(); i++) {
+    Node* value = field_value(i);
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+     if (field->is_flat()) {
+       // Flat value type field
+       vt->set_field_value(i, value->as_ValueType()->allocate_fields(kit));
+     } else if (value->is_ValueType()) {
+       // Non-flat value type field
+       vt->set_field_value(i, value->as_ValueType()->buffer(kit));
+     }
+  }
+  vt = kit->gvn().transform(vt)->as_ValueType();
+  kit->replace_in_map(this, vt);
+  return vt;
+}
+
+// Replace a buffer allocation by a dominating allocation
+static void replace_allocation(PhaseIterGVN* igvn, Node* res, Node* dom) {
+  // Remove initializing stores and GC barriers
+  for (DUIterator_Fast imax, i = res->fast_outs(imax); i < imax; i++) {
+    Node* use = res->fast_out(i);
+    if (use->is_AddP()) {
+      for (DUIterator_Fast jmax, j = use->fast_outs(jmax); j < jmax; j++) {
+        Node* store = use->fast_out(j)->isa_Store();
+        if (store != nullptr) {
+          igvn->rehash_node_delayed(store);
+          igvn->replace_in_uses(store, store->in(MemNode::Memory));
+        }
+      }
+    } else if (use->Opcode() == Op_CastP2X) {
+      if (UseG1GC && use->find_out_with(Op_XorX)->in(1) != use) {
+        // The G1 pre-barrier uses a CastP2X both for the pointer of the object
+        // we store into, as well as the value we are storing. Skip if this is a
+        // barrier for storing 'res' into another object.
+        continue;
+      }
+      BarrierSetC2* bs = BarrierSet::barrier_set()->barrier_set_c2();
+      bs->eliminate_gc_barrier(igvn, use);
+      --i; --imax;
+    }
+  }
+  igvn->replace_node(res, dom);
+}
+
+Node* ValueTypeNode::Ideal(PhaseGVN* phase, bool can_reshape) {
+  Node* oop = get_oop();
+  if (oop->isa_ValueType() && !phase->type(oop)->maybe_null()) {
+    ValueTypeNode* vtptr = oop->as_ValueType();
+    assert(value_klass() == vtptr->value_klass(), "inconsistent types");
+    set_oop(*phase, vtptr->get_oop());
+    set_is_buffered(*phase);
+    set_null_marker(*phase);
+    for (uint i = Values; i < vtptr->req(); ++i) {
+      set_req(i, vtptr->in(i));
+    }
+    return this;
+  }
+
+  // Use base oop if fields are loaded from memory, don't do so if base is the CheckCastPP of an
+  // allocation because the only case we load from a naked CheckCastPP is when we exit a
+  // constructor of a value type and we want to relinquish the larval oop there. This has a
+  // couple of benefits:
+  // - The allocation is likely to be elided earlier if it is not an input of an ValueTypeNode.
+  // - The ValueTypeNode without an allocation input is more likely to be GVN-ed. This may emerge
+  //   when we try to clone a value object.
+  // - The buffering, if needed, is delayed until it is required. This new allocation, since it is
+  //   created from an ValueTypeNode, is recognized as not having a unique identity and in the
+  //   future, we can move them around more freely such as hoisting out of loops. This is not true
+  //   for the old allocation since larval value objects do have unique identities.
+  Node* base = is_loaded(phase);
+  if (base != nullptr && !base->is_ValueType() && !phase->type(base)->maybe_null() && phase->C->allow_macro_nodes() && AllocateNode::Ideal_allocation(base) == nullptr) {
+    if (oop != base || !is_allocated(phase)) {
+      set_oop(*phase, base);
+      set_is_buffered(*phase);
+      return this;
+    }
+  }
+
+  if (can_reshape) {
+    PhaseIterGVN* igvn = phase->is_IterGVN();
+    if (is_allocated(phase)) {
+      // Search for and remove re-allocations of this value type. Ignore scalar replaceable ones,
+      // they will be removed anyway and changing the memory chain will confuse other optimizations.
+      // This can happen with late inlining when we first allocate a value type argument
+      // but later decide to inline the call after the callee code also triggered allocation.
+      for (DUIterator_Fast imax, i = fast_outs(imax); i < imax; i++) {
+        AllocateNode* alloc = fast_out(i)->isa_Allocate();
+        if (alloc != nullptr && alloc->in(AllocateNode::ValueType) == this && !alloc->_is_scalar_replaceable) {
+          // Found a re-allocation
+          Node* res = alloc->result_cast();
+          if (res != nullptr && res->is_CheckCastPP()) {
+            // Replace allocation by oop and unlink AllocateNode
+            replace_allocation(igvn, res, oop);
+            igvn->replace_input_of(alloc, AllocateNode::ValueType, igvn->C->top());
+            --i; --imax;
+          }
+        }
+      }
+    }
+  }
+
+  return nullptr;
+}
+
+ValueTypeNode* ValueTypeNode::make_uninitialized(PhaseGVN& gvn, ciValueKlass* vk, bool null_free) {
+  // Create a new ValueTypeNode with uninitialized values and nullptr oop
+  ValueTypeNode* vt = new ValueTypeNode(vk, gvn.zerocon(T_OBJECT), null_free);
+  vt->set_is_buffered(gvn, false);
+  vt->set_null_marker(gvn);
+  return vt;
+}
+
+ValueTypeNode* ValueTypeNode::make_all_zero(PhaseGVN& gvn, ciValueKlass* vk) {
+  return make_all_zero_impl(gvn, vk);
+}
+
+ValueTypeNode* ValueTypeNode::make_all_zero_impl(PhaseGVN& gvn, ciValueKlass* vk) {
+  // Create a new ValueTypeNode initialized with all zero
+  ValueTypeNode* vt = new ValueTypeNode(vk, gvn.zerocon(T_OBJECT), /* null_free= */ true);
+  vt->set_is_buffered(gvn, false);
+  vt->set_null_marker(gvn);
+  for (uint i = 0; i < vt->field_count(); ++i) {
+    ciField* field = vt->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    ciType* ft = field->type();
+    Node* value;
+    if (field->is_null_free()) {
+      value = make_all_zero_impl(gvn, ft->as_value_klass());
+    } else if (field->is_flat()) {
+      value = make_null_impl(gvn, ft->as_value_klass());
+    } else {
+      value = gvn.zerocon(ft->basic_type());
+    }
+    vt->set_field_value(i, value);
+  }
+  vt = gvn.transform(vt)->as_ValueType();
+  assert(vt->is_all_zero(&gvn), "must be the all-zero value type");
+  return vt;
+}
+
+bool ValueTypeNode::is_all_zero(PhaseGVN* gvn, bool flat) const {
+  const TypeInt* tinit = gvn->type(get_null_marker())->isa_int();
+  if (tinit == nullptr || !tinit->is_con(1)) {
+    return false; // May be null
+  }
+  for (uint i = 0; i < field_count(); ++i) {
+    Node* value = field_value(i);
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    if (field->is_null_free()) {
+      // Null-free value class field must have the all-zero value. If 'flat' is set,
+      // reject non-flat fields because they need to be initialized with an oop to a buffer.
+      if (!value->is_ValueType() || !value->as_ValueType()->is_all_zero(gvn) || (flat && !field->is_flat())) {
+        return false;
+      }
+      continue;
+    } else if (value->is_ValueType()) {
+      // Nullable value class field must be null
+      tinit = gvn->type(value->as_ValueType()->get_null_marker())->isa_int();
+      if (tinit != nullptr && tinit->is_con(0)) {
+        continue;
+      }
+      return false;
+    } else if (!gvn->type(value)->is_zero_type()) {
+      return false;
+    }
+  }
+  return true;
+}
+
+ValueTypeNode* ValueTypeNode::make_from_oop(GraphKit* kit, Node* oop, ciValueKlass* vk) {
+  return make_from_oop_impl(kit, oop, vk);
+}
+
+ValueTypeNode* ValueTypeNode::make_from_oop_impl(GraphKit* kit, Node* oop, ciValueKlass* vk) {
+  PhaseGVN& gvn = kit->gvn();
+
+  // Create and initialize an ValueTypeNode by loading all field
+  // values from a heap-allocated version and also save the oop.
+  ValueTypeNode* vt = oop->isa_ValueType();
+  if (vt != nullptr) {
+    return vt;
+  }
+
+  if (gvn.type(oop) == TypePtr::NULL_PTR) {
+    return make_null_impl(gvn, vk);
+  }
+
+  if (gvn.type(oop)->maybe_null()) {
+    // Add a null check because the oop may be null
+    Node* null_ctl = kit->top();
+    Node* not_null_oop = kit->null_check_oop(oop, &null_ctl);
+    if (kit->stopped()) {
+      // Constant null
+      kit->set_control(null_ctl);
+      vt = make_null_impl(gvn, vk);
+      kit->record_for_igvn(vt);
+      return vt;
+    }
+    vt = new ValueTypeNode(vk, not_null_oop, /* null_free= */ false);
+    vt->set_is_buffered(gvn);
+    vt->set_null_marker(gvn);
+    Node* payload_ptr = kit->basic_plus_adr(not_null_oop, vk->payload_offset());
+    vt->load(kit, not_null_oop, payload_ptr, true, true, IN_HEAP | MO_UNORDERED);
+
+    if (null_ctl != kit->top()) {
+      ValueTypeNode* null_vt = make_null_impl(gvn, vk);
+      Node* region = new RegionNode(3);
+      region->init_req(1, kit->control());
+      region->init_req(2, null_ctl);
+      vt = vt->clone_with_phis(&gvn, region, kit->map());
+      vt->merge_with(&gvn, null_vt, 2, true);
+      vt->set_oop(gvn, oop);
+      vt->set_is_buffered(gvn);
+      kit->set_control(gvn.transform(region));
+    }
+  } else {
+    // Oop can never be null
+    vt = new ValueTypeNode(vk, oop, /* null_free= */ true);
+    vt->set_is_buffered(gvn);
+    vt->set_null_marker(gvn);
+    Node* payload_ptr = kit->basic_plus_adr(oop, vk->payload_offset());
+    vt->load(kit, oop, payload_ptr, true, true, IN_HEAP | MO_UNORDERED);
+  }
+  assert(vt->is_allocated(&gvn), "value type should be allocated");
+  kit->record_for_igvn(vt);
+  return gvn.transform(vt)->as_ValueType();
+}
+
+ValueTypeNode* ValueTypeNode::make_from_flat(GraphKit* kit, ciValueKlass* vk, Node* base, Node* ptr,
+                                               bool atomic, bool immutable_memory, bool null_free, DecoratorSet decorators) {
+  return make_from_flat_impl(kit, vk, base, ptr, atomic, immutable_memory, null_free, null_free, decorators);
+}
+
+// GraphKit wrapper for the 'make_from_flat' method
+ValueTypeNode* ValueTypeNode::make_from_flat_impl(GraphKit* kit, ciValueKlass* vk, Node* base, Node* ptr, bool atomic, bool immutable_memory,
+                                                    bool null_free, bool trust_null_free_oop, DecoratorSet decorators) {
+  assert(null_free || !trust_null_free_oop, "cannot trust null-free oop when the holder object is not null-free");
+  PhaseGVN& gvn = kit->gvn();
+  bool do_atomic = atomic;
+  // With immutable memory, a non-atomic load and an atomic load are the same
+  if (immutable_memory) {
+    do_atomic = false;
+  }
+  // If there is only one flattened field, a non-atomic load and an atomic load are the same
+  if (vk->is_naturally_atomic(null_free)) {
+    do_atomic = false;
+  }
+
+  if (!do_atomic) {
+    ValueTypeNode* vt = make_uninitialized(kit->gvn(), vk, null_free);
+    if (!null_free) {
+      int nm_offset = vk->null_marker_offset_in_payload();
+      Node* nm_ptr = kit->basic_plus_adr(base, ptr, nm_offset);
+      const TypePtr* nm_ptr_type = (decorators & C2_MISMATCHED) == 0 ? gvn.type(nm_ptr)->is_ptr() : TypeRawPtr::BOTTOM;
+      Node* nm_value = kit->access_load_at(base, nm_ptr, nm_ptr_type, TypeInt::BOOL, T_BOOLEAN, decorators);
+      vt->set_req(NullMarker, nm_value);
+    }
+
+    vt->load(kit, base, ptr, immutable_memory, trust_null_free_oop, decorators);
+    return gvn.transform(vt)->as_ValueType();
+  }
+
+  assert(!immutable_memory, "immutable memory does not need explicit atomic access");
+  return LoadFlatNode::load(kit, vk, base, ptr, null_free, trust_null_free_oop, decorators);
+}
+
+ValueTypeNode* ValueTypeNode::make_from_flat_array(GraphKit* kit, ciValueKlass* vk, Node* base, Node* idx) {
+  assert(vk->maybe_flat_in_array(), "element type %s cannot be flat in array", vk->name()->as_utf8());
+  PhaseGVN& gvn = kit->gvn();
+  // The flat field loads are dependent on both the array layout checks as well as the range check.
+  DecoratorSet decorators = IN_HEAP | IS_ARRAY | MO_UNORDERED | C2_CONTROL_DEPENDENT_LOAD | C2_UNKNOWN_CONTROL_LOAD;
+  kit->C->set_flat_accesses();
+  ValueTypeNode* vt_nullable = nullptr;
+  ValueTypeNode* vt_null_free = nullptr;
+  ValueTypeNode* vt_non_atomic = nullptr;
+
+  RegionNode* region = new RegionNode(4);
+  gvn.set_type(region, Type::CONTROL);
+  kit->record_for_igvn(region);
+
+  Node* input_memory_state = kit->reset_memory();
+  kit->set_all_memory(input_memory_state);
+
+  PhiNode* mem = PhiNode::make(region, input_memory_state, Type::MEMORY, TypePtr::BOTTOM);
+  gvn.set_type(mem, Type::MEMORY);
+  kit->record_for_igvn(mem);
+
+  PhiNode* io = PhiNode::make(region, kit->i_o(), Type::ABIO);
+  gvn.set_type(io, Type::ABIO);
+  kit->record_for_igvn(io);
+
+  Node* bol_null_free = kit->null_free_array_test(base); // Argument evaluation order is undefined in C++ and since this sets control, it needs to come first
+  IfNode* iff_null_free = kit->create_and_map_if(kit->control(), bol_null_free, PROB_FAIR, COUNT_UNKNOWN);
+
+  // Nullable
+  kit->set_control(kit->IfFalse(iff_null_free));
+  if (!kit->stopped()) {
+    assert(vk->has_nullable_atomic_layout(), "element type %s does not have a nullable flat layout", vk->name()->as_utf8());
+    kit->set_all_memory(input_memory_state);
+    Node* cast = kit->cast_to_flat_array_exact(base, vk, false, true);
+    Node* ptr = kit->array_element_address(cast, idx, T_FLAT_ELEMENT);
+    vt_nullable = ValueTypeNode::make_from_flat(kit, vk, cast, ptr, true, false, false, decorators);
+
+    region->init_req(1, kit->control());
+    mem->set_req(1, kit->reset_memory());
+    io->set_req(1, kit->i_o());
+  }
+
+  // Null-free
+  kit->set_control(kit->IfTrue(iff_null_free));
+  if (!kit->stopped()) {
+    kit->set_all_memory(input_memory_state);
+
+    Node* bol_atomic = kit->null_free_atomic_array_test(base, vk);
+    IfNode* iff_atomic = kit->create_and_map_if(kit->control(), bol_atomic, PROB_FAIR, COUNT_UNKNOWN);
+
+    // Atomic
+    kit->set_control(kit->IfTrue(iff_atomic));
+    if (!kit->stopped()) {
+      assert(vk->has_null_free_atomic_layout(), "element type %s does not have a null-free atomic flat layout", vk->name()->as_utf8());
+      kit->set_all_memory(input_memory_state);
+      Node* cast = kit->cast_to_flat_array_exact(base, vk, true, true);
+      Node* ptr = kit->array_element_address(cast, idx, T_FLAT_ELEMENT);
+      vt_null_free = ValueTypeNode::make_from_flat(kit, vk, cast, ptr, true, false, true, decorators);
+
+      region->init_req(2, kit->control());
+      mem->set_req(2, kit->reset_memory());
+      io->set_req(2, kit->i_o());
+    }
+
+    // Non-Atomic
+    kit->set_control(kit->IfFalse(iff_atomic));
+    if (!kit->stopped()) {
+      assert(vk->has_null_free_non_atomic_layout(), "element type %s does not have a null-free non-atomic flat layout", vk->name()->as_utf8());
+      kit->set_all_memory(input_memory_state);
+      Node* cast = kit->cast_to_flat_array_exact(base, vk, true, false);
+      Node* ptr = kit->array_element_address(cast, idx, T_FLAT_ELEMENT);
+      vt_non_atomic = ValueTypeNode::make_from_flat(kit, vk, cast, ptr, false, false, true, decorators);
+
+      region->init_req(3, kit->control());
+      mem->set_req(3, kit->reset_memory());
+      io->set_req(3, kit->i_o());
+    }
+  }
+
+  ValueTypeNode* vt = nullptr;
+  if (vt_nullable == nullptr && vt_null_free == nullptr && vt_non_atomic == nullptr) {
+    // All paths are dead
+    vt = make_null(gvn, vk);
+  } else if (vt_nullable == nullptr && vt_null_free == nullptr) {
+    vt = vt_non_atomic;
+  } else if (vt_nullable == nullptr && vt_non_atomic == nullptr) {
+    vt = vt_null_free;
+  } else if (vt_null_free == nullptr && vt_non_atomic == nullptr) {
+    vt = vt_nullable;
+  }
+  if (vt != nullptr) {
+    kit->set_control(kit->gvn().transform(region));
+    kit->set_all_memory(kit->gvn().transform(mem));
+    kit->set_i_o(kit->gvn().transform(io));
+    return vt;
+  }
+
+  ValueTypeNode* zero = ValueTypeNode::make_null(gvn, vk);
+  vt = zero->clone_with_phis(&gvn, region);
+  if (vt_nullable != nullptr) {
+    vt = vt->merge_with(&gvn, vt_nullable, 1, false);
+  }
+  if (vt_null_free != nullptr) {
+    vt = vt->merge_with(&gvn, vt_null_free, 2, false);
+  }
+  if (vt_non_atomic != nullptr) {
+    vt = vt->merge_with(&gvn, vt_non_atomic, 3, false);
+  }
+
+  kit->set_control(kit->gvn().transform(region));
+  kit->set_all_memory(kit->gvn().transform(mem));
+  kit->set_i_o(kit->gvn().transform(io));
+  return gvn.transform(vt)->as_ValueType();
+}
+
+ValueTypeNode* ValueTypeNode::make_from_multi(GraphKit* kit, MultiNode* multi, ciValueKlass* vk, uint& base_input, bool in, bool null_free) {
+  ValueTypeNode* vt = make_uninitialized(kit->gvn(), vk, null_free);
+  if (!in || multi->is_Start()) {
+    // Keep track of the oop. The value type might already be buffered.
+    Node* oop = nullptr;
+    if (multi->is_Start()) {
+      oop = kit->gvn().transform(new ParmNode(multi->as_Start(), base_input++));
+    } else {
+      oop = kit->gvn().transform(new ProjNode(multi, base_input++));
+    }
+    vt->set_oop(kit->gvn(), oop);
+  } else {
+    Node* oop = multi->as_Call()->in(base_input++);
+    vt->set_oop(kit->gvn(), oop);
+  }
+  vt->initialize_fields(kit, multi, base_input, in, null_free, nullptr);
+  return kit->gvn().transform(vt)->as_ValueType();
+}
+
+Node* ValueTypeNode::is_loaded(PhaseGVN* phase, ciValueKlass* vk, Node* base, int holder_offset) const {
+  if (vk == nullptr) {
+    vk = value_klass();
+  }
+  for (uint i = 0; i < field_count(); ++i) {
+    ciField* field = this->field(i);
+    int offset = holder_offset + field->offset_in_bytes();
+    Node* value = field_value(i);
+    if (value->is_ValueType()) {
+      assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+      ValueTypeNode* vt = value->as_ValueType();
+      if (vt->type()->value_klass()->is_empty()) {
+        continue;
+      } else if (field->is_flat() && vt->is_ValueType()) {
+        // Check value type field load recursively
+        base = vt->as_ValueType()->is_loaded(phase, vk, base, offset - vt->type()->value_klass()->payload_offset());
+        if (base == nullptr) {
+          return nullptr;
+        }
+        continue;
+      } else {
+        value = vt->get_oop();
+        if (value->Opcode() == Op_CastPP) {
+          // Skip CastPP
+          value = value->in(1);
+        }
+      }
+    }
+    if (value->isa_DecodeN()) {
+      // Skip DecodeN
+      value = value->in(1);
+    }
+    if (value->isa_Load()) {
+      // Check if base and offset of field load matches value type layout
+      intptr_t loffset = 0;
+      Node* lbase = AddPNode::Ideal_base_and_offset(value->in(MemNode::Address), phase, loffset);
+      if (lbase == nullptr || (lbase != base && base != nullptr) || loffset != offset) {
+        return nullptr;
+      } else if (base == nullptr) {
+        // Set base and check if pointer type matches
+        base = lbase;
+        const TypeInstPtr* vtptr = phase->type(base)->isa_instptr();
+        if (vtptr == nullptr || !vtptr->instance_klass()->equals(vk)) {
+          return nullptr;
+        }
+      }
+    } else {
+      return nullptr;
+    }
+  }
+  return base;
+}
+
+Node* ValueTypeNode::tagged_klass(ciValueKlass* vk, PhaseGVN& gvn) {
+  const TypeKlassPtr* tk = TypeKlassPtr::make(vk);
+  intptr_t bits = tk->get_con();
+  set_nth_bit(bits, 0);
+  return gvn.longcon((jlong)bits);
+}
+
+void ValueTypeNode::pass_fields(GraphKit* kit, Node* n, uint& base_input, bool in, bool null_free, bool root) {
+  if (root) {
+    if (is_allocated(&kit->gvn())) {
+      // Keep the information that 'this' is buffered
+      n->init_req(base_input++, this);
+    } else {
+      n->init_req(base_input++, get_oop());
+    }
+  }
+  if (!null_free && in) {
+    n->init_req(base_input++, get_null_marker());
+  }
+  for (uint i = 0; i < field_count(); i++) {
+    Node* arg = field_value(i);
+    ciField* field = this->field(i);
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    if (field->is_flat()) {
+      // Flat value type field
+      arg->as_ValueType()->pass_fields(kit, n, base_input, in);
+      if (!field->is_null_free()) {
+        assert(field->null_marker_offset() != -1, "inconsistency");
+        n->init_req(base_input++, arg->as_ValueType()->get_null_marker());
+      }
+    } else {
+      if (arg->is_ValueType()) {
+        // Non-flat value type field
+        ValueTypeNode* vt = arg->as_ValueType();
+        assert(n->Opcode() != Op_Return || vt->is_allocated(&kit->gvn()), "value type field should be allocated on return");
+        arg = vt->buffer(kit);
+      }
+      // Initialize call/return arguments
+      n->init_req(base_input++, arg);
+      if (field->type()->size() == 2) {
+        n->init_req(base_input++, kit->top());
+      }
+    }
+  }
+}
+
+void ValueTypeNode::initialize_fields(GraphKit* kit, MultiNode* multi, uint& base_input, bool in, bool no_null_marker, Node* null_check_region) {
+  PhaseGVN& gvn = kit->gvn();
+  Node* null_marker = nullptr;
+  if (!no_null_marker) {
+    // Nullable value type
+    if (in) {
+      // Set null marker
+      if (multi->is_Start()) {
+        null_marker = gvn.transform(new ParmNode(multi->as_Start(), base_input));
+      } else {
+        null_marker = multi->as_Call()->in(base_input);
+      }
+      set_req(NullMarker, null_marker);
+      base_input++;
+    }
+    // Add a null check to make subsequent loads dependent on
+    assert(null_check_region == nullptr, "already set");
+    if (null_marker == nullptr) {
+      // Will only be initialized below, use dummy node for now
+      null_marker = new Node(1);
+      null_marker->init_req(0, kit->control()); // Add an input to prevent dummy from being dead
+      gvn.set_type_bottom(null_marker);
+    }
+    Node* null_ctrl = kit->top();
+    kit->null_check_common(null_marker, T_INT, false, &null_ctrl);
+    Node* non_null_ctrl = kit->control();
+    null_check_region = new RegionNode(3);
+    null_check_region->init_req(1, non_null_ctrl);
+    null_check_region->init_req(2, null_ctrl);
+    null_check_region = gvn.transform(null_check_region);
+    kit->set_control(null_check_region);
+  }
+
+  for (uint i = 0; i < field_count(); ++i) {
+    ciField* field = this->field(i);
+    ciType* type = field->type();
+    Node* parm = nullptr;
+    assert(!field->is_flat() || field->type()->is_value_klass(), "must be a value type");
+    if (field->is_flat()) {
+      // Flat value type field
+      ValueTypeNode* vt = make_uninitialized(gvn, type->as_value_klass(), field->is_null_free());
+      vt->initialize_fields(kit, multi, base_input, in, true, null_check_region);
+      if (!field->is_null_free()) {
+        assert(field->null_marker_offset() != -1, "inconsistency");
+        Node* null_marker_field_vt = nullptr;
+        if (multi->is_Start()) {
+          null_marker_field_vt = gvn.transform(new ParmNode(multi->as_Start(), base_input));
+        } else if (in) {
+          null_marker_field_vt = multi->as_Call()->in(base_input);
+        } else {
+          null_marker_field_vt = gvn.transform(new ProjNode(multi->as_Call(), base_input));
+        }
+        vt->set_req(NullMarker, null_marker_field_vt);
+        base_input++;
+      }
+      parm = gvn.transform(vt);
+    } else {
+      if (multi->is_Start()) {
+        assert(in, "return from start?");
+        parm = gvn.transform(new ParmNode(multi->as_Start(), base_input));
+      } else if (in) {
+        parm = multi->as_Call()->in(base_input);
+      } else {
+        parm = gvn.transform(new ProjNode(multi->as_Call(), base_input));
+      }
+      base_input += type->size();
+    }
+    assert(parm != nullptr, "should never be null");
+    assert(field_value(i) == nullptr, "already set");
+    set_field_value(i, parm);
+    gvn.record_for_igvn(parm);
+  }
+  // The last argument is used to pass the null marker to compiled code
+  if (!no_null_marker && !in) {
+    Node* cmp = null_marker->raw_out(0);
+    null_marker = gvn.transform(new ProjNode(multi->as_Call(), base_input));
+    set_req(NullMarker, null_marker);
+    gvn.hash_delete(cmp);
+    cmp->set_req(1, null_marker);
+    gvn.hash_find_insert(cmp);
+    gvn.record_for_igvn(cmp);
+    base_input++;
+  }
+}
+
+// Search for multiple allocations of this value type and try to replace them by dominating allocations.
+// Equivalent ValueTypeNodes are merged by GVN, so we just need to search for AllocateNode users to find redundant allocations.
+void ValueTypeNode::remove_redundant_allocations(PhaseIdealLoop* phase) const {
+  PhaseIterGVN* igvn = &phase->igvn();
+  // Search for allocations of this value type. Ignore scalar replaceable ones, they
+  // will be removed anyway and changing the memory chain will confuse other optimizations.
+  for (DUIterator_Fast imax, i = fast_outs(imax); i < imax; i++) {
+    AllocateNode* alloc = fast_out(i)->isa_Allocate();
+    if (alloc != nullptr && alloc->in(AllocateNode::ValueType) == this && !alloc->_is_scalar_replaceable) {
+      Node* res = alloc->result_cast();
+      if (res == nullptr || !res->is_CheckCastPP()) {
+        break; // No unique CheckCastPP
+      }
+      // Search for a dominating allocation of the same value type
+      Node* res_dom = res;
+      for (DUIterator_Fast jmax, j = fast_outs(jmax); j < jmax; j++) {
+        AllocateNode* alloc_other = fast_out(j)->isa_Allocate();
+        if (alloc_other != nullptr && alloc_other->in(AllocateNode::ValueType) == this && !alloc_other->_is_scalar_replaceable) {
+          Node* res_other = alloc_other->result_cast();
+          if (res_other != nullptr && res_other->is_CheckCastPP() && res_other != res_dom &&
+              phase->is_dominator(res_other->in(0), res_dom->in(0))) {
+            res_dom = res_other;
+          }
+        }
+      }
+      if (res_dom != res) {
+        // Replace allocation by dominating one.
+        replace_allocation(igvn, res, res_dom);
+        // The result of the dominated allocation is now unused and will be removed
+        // later in PhaseMacroExpand::eliminate_allocate_node to not confuse loop opts.
+        igvn->_worklist.push(alloc);
+      }
+    }
+  }
+}
+
+ValueTypeNode* ValueTypeNode::make_null(PhaseGVN& gvn, ciValueKlass* vk, bool transform) {
+  return make_null_impl(gvn, vk, transform);
+}
+
+ValueTypeNode* ValueTypeNode::make_null_impl(PhaseGVN& gvn, ciValueKlass* vk, bool transform) {
+  ValueTypeNode* vt = new ValueTypeNode(vk, gvn.zerocon(T_OBJECT), /* null_free= */ false);
+  vt->set_is_buffered(gvn);
+  vt->set_null_marker(gvn, gvn.intcon(0));
+  for (uint i = 0; i < vt->field_count(); i++) {
+    ciField* field = vt->field(i);
+    ciType* ft = field->type();
+    Node* value;
+    if (field->is_flat()) {
+      value = make_null_impl(gvn, ft->as_value_klass());
+    } else {
+      value = gvn.zerocon(ft->basic_type());
+    }
+    vt->set_field_value(i, value);
+  }
+  return transform ? gvn.transform(vt)->as_ValueType() : vt;
+}
+
+ValueTypeNode* ValueTypeNode::clone_if_required(PhaseGVN* gvn, SafePointNode* map, bool safe_for_replace) {
+  if (!safe_for_replace || (map == nullptr && outcnt() != 0)) {
+    return clone()->as_ValueType();
+  }
+  for (DUIterator_Fast imax, i = fast_outs(imax); i < imax; i++) {
+    if (fast_out(i) != map) {
+      return clone()->as_ValueType();
+    }
+  }
+  gvn->hash_delete(this);
+  return this;
+}
+
+const Type* ValueTypeNode::Value(PhaseGVN* phase) const {
+  Node* oop = get_oop();
+  const Type* toop = phase->type(oop);
+#ifdef ASSERT
+  if (oop->is_Con() && toop->is_zero_type() && _type->isa_oopptr()->is_known_instance()) {
+    // We are not allocated (anymore) and should therefore not have an instance id
+    dump(1);
+    assert(false, "Unbuffered value type should not have known instance id");
+  }
+#endif
+  if (toop == Type::TOP) {
+    return Type::TOP;
+  }
+  const Type* t = toop->filter_speculative(_type);
+  // Because of contradicting type profiling, we can end up with top as speculative type,
+  // which would then get removed by cleanup_speculative. In this case we have to run filter_speculative
+  // again, otherwise we would break the idempotence of Value
+  if (t->speculative() == nullptr && toop->speculative() != nullptr) {
+    t = toop->filter_speculative(t);
+  }
+  if (t->singleton()) {
+    // Don't replace ValueType by a constant
+    t = _type;
+  }
+  const Type* tinit = phase->type(in(NullMarker));
+  if (tinit == Type::TOP) {
+    return Type::TOP;
+  }
+  if (tinit->isa_int() && tinit->is_int()->is_con(1)) {
+    t = t->join_speculative(TypePtr::NOTNULL);
+  }
+  return t;
+}
+
+ValueTypeNode* LoadFlatNode::load(GraphKit* kit, ciValueKlass* vk, Node* base, Node* ptr, bool null_free, bool trust_null_free_oop, DecoratorSet decorators) {
+  int output_type_size = vk->nof_nonstatic_fields() + (null_free ? 0 : 1);
+  const Type** output_types = TypeTuple::fields(output_type_size);
+  collect_field_types(vk, output_types + TypeFunc::Parms, 0, output_type_size, null_free, trust_null_free_oop);
+  const TypeTuple* type = TypeTuple::make(output_type_size + TypeFunc::Parms, output_types);
+
+  LoadFlatNode* load = new LoadFlatNode(vk, type, null_free, decorators);
+  load->init_req(TypeFunc::Control, kit->control());
+  load->init_req(TypeFunc::I_O, kit->top());
+  load->init_req(TypeFunc::Memory, kit->reset_memory());
+  load->init_req(TypeFunc::FramePtr, kit->frameptr());
+  load->init_req(TypeFunc::ReturnAdr, kit->top());
+
+  load->init_req(TypeFunc::Parms, base);
+  load->init_req(TypeFunc::Parms + 1, ptr);
+  kit->kill_dead_locals();
+  kit->add_safepoint_edges(load);
+  load = kit->gvn().transform(load)->as_LoadFlat();
+  kit->record_for_igvn(load);
+
+  kit->set_control(kit->gvn().transform(new ProjNode(load, TypeFunc::Control)));
+  kit->set_all_memory(kit->gvn().transform(new ProjNode(load, TypeFunc::Memory)));
+  return load->collect_projs(kit, vk, TypeFunc::Parms, null_free);
+}
+
+bool LoadFlatNode::expand_constant(PhaseIterGVN& igvn, ciInstance* inst) const {
+  precond(inst != nullptr);
+  assert(igvn.delay_transform(), "transformation must be delayed");
+  if ((_decorators & C2_MISMATCHED) != 0) {
+    return false;
+  }
+
+  GraphKit kit(this, igvn);
+  for (int i = 0; i < _vk->nof_nonstatic_fields(); i++) {
+    ProjNode* proj_out = proj_out_or_null(TypeFunc::Parms + i);
+    if (proj_out == nullptr) {
+      continue;
+    }
+
+    ciField* field = _vk->nonstatic_field_at(i);
+    BasicType bt = field->type()->basic_type();
+    if (inst == nullptr) {
+      Node* cst_node = igvn.zerocon(bt);
+      igvn.replace_node(proj_out, cst_node);
+    } else {
+      bool is_unsigned_load = bt == T_BOOLEAN || bt == T_CHAR;
+      const Type* cst_type = Type::make_constant_from_field(field, inst, bt, is_unsigned_load);
+      Node* cst_node = igvn.makecon(cst_type);
+      igvn.replace_node(proj_out, cst_node);
+    }
+  }
+
+  if (!_null_free) {
+    ProjNode* proj_out = proj_out_or_null(TypeFunc::Parms + _vk->nof_nonstatic_fields());
+    if (proj_out != nullptr) {
+      igvn.replace_node(proj_out, igvn.intcon(1));
+    }
+  }
+
+  Node* old_ctrl = proj_out_or_null(TypeFunc::Control);
+  if (old_ctrl != nullptr) {
+    igvn.replace_node(old_ctrl, kit.control());
+  }
+  Node* old_mem = proj_out_or_null(TypeFunc::Memory);
+  Node* new_mem = kit.reset_memory();
+  if (old_mem != nullptr) {
+    igvn.replace_node(old_mem, new_mem);
+  }
+  return true;
+}
+
+bool LoadFlatNode::expand_non_atomic(PhaseIterGVN& igvn) const {
+  assert(igvn.delay_transform(), "transformation must be delayed");
+  if ((_decorators & C2_MISMATCHED) != 0) {
+    return false;
+  }
+
+  GraphKit kit(this, igvn);
+  Node* base = this->base();
+  Node* ptr = this->ptr();
+
+  for (int i = 0; i < _vk->nof_nonstatic_fields(); i++) {
+    ProjNode* proj_out = proj_out_or_null(TypeFunc::Parms + i);
+    if (proj_out == nullptr) {
+      continue;
+    }
+
+    ciField* field = _vk->nonstatic_field_at(i);
+    Node* field_ptr = kit.basic_plus_adr(base, ptr, field->offset_in_bytes() - _vk->payload_offset());
+    const TypePtr* field_ptr_type = field_ptr->Value(&igvn)->is_ptr();
+    igvn.set_type(field_ptr, field_ptr_type);
+
+    Node* field_value = kit.access_load_at(base, field_ptr, field_ptr_type, igvn.type(proj_out), field->type()->basic_type(), _decorators);
+    igvn.replace_node(proj_out, field_value);
+  }
+
+  if (!_null_free) {
+    ProjNode* proj_out = proj_out_or_null(TypeFunc::Parms + _vk->nof_nonstatic_fields());
+    if (proj_out != nullptr) {
+      Node* null_marker_ptr = kit.basic_plus_adr(base, ptr, _vk->null_marker_offset_in_payload());
+      const TypePtr* null_marker_ptr_type = null_marker_ptr->Value(&igvn)->is_ptr();
+      igvn.set_type(null_marker_ptr, null_marker_ptr_type);
+      Node* null_marker_value = kit.access_load_at(base, null_marker_ptr, null_marker_ptr_type, TypeInt::BOOL, T_BOOLEAN, _decorators);
+      igvn.replace_node(proj_out, null_marker_value);
+    }
+  }
+
+  Node* old_ctrl = proj_out_or_null(TypeFunc::Control);
+  if (old_ctrl != nullptr) {
+    igvn.replace_node(old_ctrl, kit.control());
+  }
+  Node* old_mem = proj_out_or_null(TypeFunc::Memory);
+  Node* new_mem = kit.reset_memory();
+  if (old_mem != nullptr) {
+    igvn.replace_node(old_mem, new_mem);
+  }
+  return true;
+}
+
+void LoadFlatNode::expand_atomic(PhaseIterGVN& igvn) const {
+  assert(igvn.delay_transform(), "transformation must be delayed");
+  GraphKit kit(this, igvn);
+  Node* base = this->base();
+  Node* ptr = this->ptr();
+
+  BasicType payload_bt = _vk->atomic_size_to_basic_type(_null_free);
+  kit.insert_mem_bar(Op_MemBarCPUOrder);
+  Node* payload = kit.access_load_at(base, ptr, TypeRawPtr::BOTTOM, Type::get_const_basic_type(payload_bt), payload_bt,
+                                     _decorators | C2_MISMATCHED | C2_CONTROL_DEPENDENT_LOAD | C2_UNKNOWN_CONTROL_LOAD, kit.control());
+  kit.insert_mem_bar(Op_MemBarCPUOrder);
+
+  Node* old_ctrl = proj_out_or_null(TypeFunc::Control);
+  if (old_ctrl != nullptr) {
+    igvn.replace_node(old_ctrl, kit.control());
+  }
+  Node* old_mem = proj_out_or_null(TypeFunc::Memory);
+  Node* new_mem = kit.reset_memory();
+  if (old_mem != nullptr) {
+    igvn.replace_node(old_mem, new_mem);
+  }
+
+  expand_projs_atomic(igvn, kit.control(), payload);
+}
+
+void LoadFlatNode::collect_field_types(ciValueKlass* vk, const Type** field_types, int idx, int limit, bool null_free, bool trust_null_free_oop) {
+  assert(null_free || !trust_null_free_oop, "cannot trust null-free oop when the holder object is not null-free");
+  for (int i = 0; i < vk->nof_declared_nonstatic_fields(); i++) {
+    ciField* field = vk->declared_nonstatic_field_at(i);
+    if (field->is_flat()) {
+      ciValueKlass* field_klass = field->type()->as_value_klass();
+      collect_field_types(field_klass, field_types, idx, limit, field->is_null_free(), trust_null_free_oop && field->is_null_free());
+      idx += field_klass->nof_nonstatic_fields() + (field->is_null_free() ? 0 : 1);
+      continue;
+    }
+
+    const Type* field_type = Type::get_const_type(field->type());
+    if (trust_null_free_oop && field->is_null_free()) {
+      field_type = field_type->filter(TypePtr::NOTNULL);
+    }
+
+    assert(idx >= 0 && idx < limit, "field type out of bounds, %d - %d", idx, limit);
+    field_types[idx] = field_type;
+    idx++;
+  }
+
+  if (!null_free) {
+    assert(idx >= 0 && idx < limit, "field type out of bounds, %d - %d", idx, limit);
+    field_types[idx] = TypeInt::BOOL;
+  }
+}
+
+// Create an ValueTypeNode from a LoadFlatNode with its fields being extracted from the
+// LoadFlatNode
+ValueTypeNode* LoadFlatNode::collect_projs(GraphKit* kit, ciValueKlass* vk, int proj_con, bool null_free) {
+  PhaseGVN& gvn = kit->gvn();
+  ValueTypeNode* res = ValueTypeNode::make_uninitialized(gvn, vk, null_free);
+  for (int i = 0; i < vk->nof_declared_nonstatic_fields(); i++) {
+    ciField* field = vk->declared_nonstatic_field_at(i);
+    Node* field_value;
+    if (field->is_flat()) {
+      ciValueKlass* field_klass = field->type()->as_value_klass();
+      field_value = collect_projs(kit, field_klass, proj_con, field->is_null_free());
+      proj_con += field_klass->nof_nonstatic_fields() + (field->is_null_free() ? 0 : 1);
+    } else {
+      field_value = gvn.transform(new ProjNode(this, proj_con));
+      proj_con++;
+    }
+    res->set_field_value(i, field_value);
+  }
+
+  if (null_free) {
+    res->set_null_marker(gvn);
+  } else {
+    res->set_null_marker(gvn, gvn.transform(new ProjNode(this, proj_con)));
+  }
+  return gvn.transform(res)->as_ValueType();
+}
+
+// Extract the values of the flattened fields from the loaded payload
+void LoadFlatNode::expand_projs_atomic(PhaseIterGVN& igvn, Node* ctrl, Node* payload) const {
+  BasicType payload_bt = _vk->atomic_size_to_basic_type(_null_free);
+  for (int i = 0; i < _vk->nof_nonstatic_fields(); i++) {
+    ProjNode* proj_out = proj_out_or_null(TypeFunc::Parms + i);
+    if (proj_out == nullptr) {
+      continue;
+    }
+
+    ciField* field = _vk->nonstatic_field_at(i);
+    int field_offset = field->offset_in_bytes() - _vk->payload_offset();
+    const Type* field_type = igvn.type(proj_out);
+    Node* field_value = get_payload_value(igvn, ctrl, payload_bt, payload, field_type, field->type()->basic_type(), field_offset);
+    igvn.replace_node(proj_out, field_value);
+  }
+
+  if (!_null_free) {
+    ProjNode* proj_out = proj_out_or_null(TypeFunc::Parms + _vk->nof_nonstatic_fields());
+    if (proj_out == nullptr) {
+      return;
+    }
+
+    int null_marker_offset = _vk->null_marker_offset_in_payload();
+    Node* null_marker_value = get_payload_value(igvn, ctrl, payload_bt, payload, TypeInt::BOOL, T_BOOLEAN, null_marker_offset);
+    igvn.replace_node(proj_out, null_marker_value);
+  }
+}
+
+Node* LoadFlatNode::get_payload_value(PhaseIterGVN& igvn, Node* ctrl, BasicType payload_bt, Node* payload, const Type* value_type, BasicType value_bt, int offset) {
+  assert((offset + type2aelembytes(value_bt)) <= type2aelembytes(payload_bt), "Value does not fit into payload");
+  Node* value = nullptr;
+  // Shift to the right position in the long value
+  Node* shift_val = igvn.intcon(offset << LogBitsPerByte);
+  if (payload_bt == T_LONG) {
+    value = igvn.transform(new URShiftLNode(payload, shift_val));
+    value = igvn.transform(new ConvL2INode(value));
+  } else {
+    value = igvn.transform(new URShiftINode(payload, shift_val));
+  }
+
+  if (value_bt == T_INT) {
+    return value;
+  } else if (!is_java_primitive(value_bt)) {
+    assert(UseCompressedOops && payload_bt == T_LONG, "Naturally atomic");
+    value = igvn.transform(new CastI2NNode(ctrl, value, value_type->make_narrowoop()));
+    value = igvn.transform(new DecodeNNode(value, value_type));
+
+    // Similar to CheckCastPP nodes with raw input, CastI2N nodes require special handling in 'PhaseCFG::schedule_late' to ensure the
+    // register allocator does not move the CastI2N below a safepoint. This is necessary to avoid having the raw pointer span a safepoint,
+    // making it opaque to the GC. Unlike CheckCastPPs, which need extra handling in 'Scheduling::ComputeRegisterAntidependencies' due to
+    // scalarization, CastI2N nodes are always used by a load if scalarization happens which inherently keeps them pinned above the safepoint.
+    return value;
+  } else {
+    // Make sure to zero unused bits in the 32-bit value
+    return Compile::narrow_value(value_bt, value, value_type, &igvn, true);
+  }
+}
+
+void StoreFlatNode::store(GraphKit* kit, Node* base, Node* ptr, ValueTypeNode* value, bool null_free, DecoratorSet decorators) {
+  value = value->allocate_fields(kit);
+  StoreFlatNode* store = new StoreFlatNode(null_free, decorators);
+  store->init_req(TypeFunc::Control, kit->control());
+  store->init_req(TypeFunc::I_O, kit->top());
+  store->init_req(TypeFunc::Memory, kit->reset_memory());
+  store->init_req(TypeFunc::FramePtr, kit->frameptr());
+  store->init_req(TypeFunc::ReturnAdr, kit->top());
+
+  store->init_req(TypeFunc::Parms, base);
+  store->init_req(TypeFunc::Parms + 1, ptr);
+  store->init_req(TypeFunc::Parms + 2, value);
+  kit->kill_dead_locals();
+  kit->add_safepoint_edges(store);
+  store = kit->gvn().transform(store)->as_StoreFlat();
+  kit->record_for_igvn(store);
+
+  kit->set_control(kit->gvn().transform(new ProjNode(store, TypeFunc::Control)));
+  kit->set_all_memory(kit->gvn().transform(new ProjNode(store, TypeFunc::Memory)));
+}
+
+bool StoreFlatNode::expand_non_atomic(PhaseIterGVN& igvn) const {
+  assert(igvn.delay_transform(), "transformation must be delayed");
+  if ((_decorators & C2_MISMATCHED) != 0) {
+    return false;
+  }
+
+  GraphKit kit(this, igvn);
+  Node* base = this->base();
+  Node* ptr = this->ptr();
+  ValueTypeNode* value = this->value();
+
+  ciValueKlass* vk = igvn.type(value)->value_klass();
+  for (int i = 0; i < vk->nof_nonstatic_fields(); i++) {
+    ciField* field = vk->nonstatic_field_at(i);
+    Node* field_ptr = kit.basic_plus_adr(base, ptr, field->offset_in_bytes() - vk->payload_offset());
+    const TypePtr* field_ptr_type = field_ptr->Value(&igvn)->is_ptr();
+    igvn.set_type(field_ptr, field_ptr_type);
+    Node* field_value = value->field_value_by_offset(field->offset_in_bytes(), true);
+    kit.access_store_at(base, field_ptr, field_ptr_type, field_value, igvn.type(field_value), field->type()->basic_type(), _decorators);
+  }
+
+  if (!_null_free) {
+    Node* null_marker_ptr = kit.basic_plus_adr(base, ptr, vk->null_marker_offset_in_payload());
+    const TypePtr* null_marker_ptr_type = null_marker_ptr->Value(&igvn)->is_ptr();
+    igvn.set_type(null_marker_ptr, null_marker_ptr_type);
+    Node* null_marker_value = value->get_null_marker();
+    kit.access_store_at(base, null_marker_ptr, null_marker_ptr_type, null_marker_value, TypeInt::BOOL, T_BOOLEAN, _decorators);
+  }
+
+  Node* old_ctrl = proj_out_or_null(TypeFunc::Control);
+  if (old_ctrl != nullptr) {
+    igvn.replace_node(old_ctrl, kit.control());
+  }
+  Node* old_mem = proj_out_or_null(TypeFunc::Memory);
+  Node* new_mem = kit.reset_memory();
+  if (old_mem != nullptr) {
+    igvn.replace_node(old_mem, new_mem);
+  }
+  return true;
+}
+
+void StoreFlatNode::expand_atomic(PhaseIterGVN& igvn) const {
+  // Convert to a payload value <= 64-bit and write atomically.
+  // The payload might contain at most two oop fields that must be narrow because otherwise they would be 64-bit
+  // in size and would then be written by a "normal" oop store. If the payload contains oops, its size is always
+  // 64-bit because the next smaller (power-of-two) size would be 32-bit which could only hold one narrow oop that
+  // would then be written by a normal narrow oop store. These properties are asserted in 'convert_to_payload'.
+  assert(igvn.delay_transform(), "transformation must be delayed");
+  GraphKit kit(this, igvn);
+  Node* base = this->base();
+  Node* ptr = this->ptr();
+  ValueTypeNode* value = this->value();
+
+  int oop_off_1 = -1;
+  int oop_off_2 = -1;
+  Node* payload = convert_to_payload(igvn, kit.control(), value, _null_free, oop_off_1, oop_off_2);
+
+  ciValueKlass* vk = igvn.type(value)->value_klass();
+  assert(oop_off_1 == -1 || oop_off_1 == 0 || oop_off_1 == 4, "invalid layout for %s, first oop at offset %d", vk->name()->as_utf8(), oop_off_1);
+  assert(oop_off_2 == -1 || oop_off_2 == 4, "invalid layout for %s, second oop at offset %d", vk->name()->as_utf8(), oop_off_2);
+  BasicType payload_bt = vk->atomic_size_to_basic_type(_null_free);
+  kit.insert_mem_bar(Op_MemBarCPUOrder);
+  if (!UseG1GC || oop_off_1 == -1) {
+    // No oop fields or no late barrier expansion. Emit an atomic store of the payload and add GC barriers if needed.
+    assert(oop_off_2 == -1 || !UseG1GC, "sanity");
+    // ZGC does not support compressed oops, so only one oop can be in the payload which is written by a "normal" oop store.
+    assert((oop_off_1 == -1 && oop_off_2 == -1) || !UseZGC, "ZGC does not support embedded oops in flat fields");
+    kit.access_store_at(base, ptr, TypeRawPtr::BOTTOM, payload, Type::get_const_basic_type(payload_bt), payload_bt, _decorators | C2_MISMATCHED, true, value);
+  } else {
+    // Contains oops and requires late barrier expansion. Emit a special store node that allows to emit GC barriers in the backend.
+    assert(UseG1GC, "Unexpected GC");
+    assert(payload_bt == T_LONG, "Unexpected payload type");
+    // If one oop, set the offset (if no offset is set, two oops are assumed by the backend)
+    Node* oop_offset = (oop_off_2 == -1) ? igvn.intcon(oop_off_1) : nullptr;
+    Node* mem = kit.reset_memory();
+    kit.set_all_memory(mem);
+    Node* store = igvn.transform(new StoreLSpecialNode(kit.control(), mem, ptr, TypeRawPtr::BOTTOM, payload, oop_offset, MemNode::unordered));
+    kit.set_memory(store, TypeRawPtr::BOTTOM);
+  }
+  kit.insert_mem_bar(Op_MemBarCPUOrder);
+
+  Node* old_ctrl = proj_out_or_null(TypeFunc::Control);
+  if (old_ctrl != nullptr) {
+    igvn.replace_node(old_ctrl, kit.control());
+  }
+  Node* old_mem = proj_out_or_null(TypeFunc::Memory);
+  Node* new_mem = kit.reset_memory();
+  if (old_mem != nullptr) {
+    igvn.replace_node(old_mem, new_mem);
+  }
+}
+
+// Convert the field values to a payload value of type 'bt'
+Node* StoreFlatNode::convert_to_payload(PhaseIterGVN& igvn, Node* ctrl, ValueTypeNode* value, bool null_free, int& oop_off_1, int& oop_off_2) {
+  ciValueKlass* vk = igvn.type(value)->value_klass();
+  BasicType payload_bt = vk->atomic_size_to_basic_type(null_free);
+  Node* payload = igvn.zerocon(payload_bt);
+  if (!null_free) {
+    // Set the null marker
+    payload = set_payload_value(igvn, payload_bt, payload, T_BOOLEAN, value->get_null_marker(), vk->null_marker_offset_in_payload());
+  }
+
+  // Iterate over the fields and add their values to the payload
+  for (int i = 0; i < vk->nof_nonstatic_fields(); i++) {
+    ciField* field = vk->nonstatic_field_at(i);
+    Node* field_value = value->field_value_by_offset(field->offset_in_bytes(), true);
+    ciType* field_klass = field->type();
+    BasicType field_bt = field_klass->basic_type();
+    int field_offset_in_payload = field->offset_in_bytes() - vk->payload_offset();
+    if (!field_klass->is_primitive_type()) {
+      // Narrow oop field
+      assert(UseCompressedOops && payload_bt == T_LONG, "Naturally atomic");
+      if (oop_off_1 == -1) {
+        oop_off_1 = field_offset_in_payload;
+      } else {
+        assert(oop_off_2 == -1, "already set");
+        oop_off_2 = field_offset_in_payload;
+      }
+
+      const Type* val_type = Type::get_const_type(field_klass)->make_narrowoop();
+      if (field_value->is_ValueType()) {
+        assert(field_value->as_ValueType()->is_allocated(&igvn), "must be allocated");
+      }
+
+      field_value = igvn.transform(new EncodePNode(field_value, val_type));
+      field_value = igvn.transform(new CastP2XNode(ctrl, field_value));
+      field_value = igvn.transform(new ConvL2INode(field_value));
+      field_bt = T_INT;
+    }
+    payload = set_payload_value(igvn, payload_bt, payload, field_bt, field_value, field_offset_in_payload);
+  }
+
+  return payload;
+}
+
+Node* StoreFlatNode::set_payload_value(PhaseIterGVN& igvn, BasicType payload_bt, Node* payload, BasicType val_bt, Node* value, int offset) {
+  assert((offset + type2aelembytes(val_bt)) <= type2aelembytes(payload_bt), "Value does not fit into payload");
+
+  // Make sure to zero unused bits in the 32-bit value
+  if (val_bt == T_BYTE || val_bt == T_BOOLEAN) {
+    value = igvn.transform(new AndINode(value, igvn.intcon(0xFF)));
+  } else if (val_bt == T_CHAR || val_bt == T_SHORT) {
+    value = igvn.transform(new AndINode(value, igvn.intcon(0xFFFF)));
+  } else if (val_bt == T_FLOAT) {
+    value = igvn.transform(new MoveF2INode(value));
+  } else {
+    assert(val_bt == T_INT, "Unsupported type: %s", type2name(val_bt));
+  }
+
+  Node* shift_val = igvn.intcon(offset << LogBitsPerByte);
+  if (payload_bt == T_LONG) {
+    // Convert to long and remove the sign bit (the backend will fold this and emit a zero extend i2l)
+    value = igvn.transform(new ConvI2LNode(value));
+    value = igvn.transform(new AndLNode(value, igvn.longcon(0xFFFFFFFF)));
+
+    Node* shift_value = igvn.transform(new LShiftLNode(value, shift_val));
+    payload = new OrLNode(shift_value, payload);
+  } else {
+    Node* shift_value = igvn.transform(new LShiftINode(value, shift_val));
+    payload = new OrINode(shift_value, payload);
+  }
+  return igvn.transform(payload);
+}
+
+const Type* LoadFlatNode::Value(PhaseGVN* phase) const {
+  if (phase->type(in(TypeFunc::Control)) == Type::TOP || phase->type(in(TypeFunc::Memory)) == Type::TOP ||
+      phase->type(base()) == Type::TOP || phase->type(ptr()) == Type::TOP) {
+    return Type::TOP;
+  }
+  return bottom_type();
+}
+
+const Type* StoreFlatNode::Value(PhaseGVN* phase) const {
+  Node* val = in(TypeFunc::Parms + 2);
+  if (phase->type(in(TypeFunc::Control)) == Type::TOP || phase->type(in(TypeFunc::Memory)) == Type::TOP ||
+      phase->type(base()) == Type::TOP || phase->type(ptr()) == Type::TOP || phase->type(val) == Type::TOP) {
+    return Type::TOP;
+  }
+  assert(val->is_ValueType(), "must be ValueTypeNode: %s", val->Name());
+  return bottom_type();
+}
+
+bool LoadFlatNode::is_mismatched() const {
+  return (_decorators & C2_MISMATCHED) != 0;
+}
+
+bool StoreFlatNode::is_mismatched() const {
+  return (_decorators & C2_MISMATCHED) != 0;
+}

