+/*
+ * @test
+ * @summary Test loads from a dead ValueTypeNode with top field values.
+ * @bug 8384202
+ * @requires vm.compiler2.enabled
+ * @requires (vm.opt.PreloadClasses == null | vm.opt.PreloadClasses == "true")
+ * @enablePreview
+ * @modules java.base/jdk.internal.vm.annotation
+ * @run main ${test.main.class}
+ * @run main/othervm -XX:+UnlockDiagnosticVMOptions -XX:+IgnoreUnrecognizedVMOptions
+ *                   -XX:+StressIGVN -XX:StressSeed=8 -XX:+AlwaysIncrementalInline
+ *                   ${test.main.class}
+ */
+public value class TestDeadValueTypeFieldOffset {
+    MyValue valueField1;
+    @NullRestricted
+    MyValue valueField2;
+
+    TestDeadValueTypeFieldOffset(MyValue valueField1, MyValue valueField2) {
+        this.valueField1 = valueField1;
+        this.valueField2 = valueField2;
+    }
+
+    TestDeadValueTypeFieldOffset test1() {
+        return new TestDeadValueTypeFieldOffset(null, valueField2);
+    }
+
+    TestDeadValueTypeFieldOffset test2() {
+        return new TestDeadValueTypeFieldOffset(valueField1, null);
+    }
+
+    @LooselyConsistentValue
+    static value class NestedValue {
+        int x;
+        int y;
+
+        NestedValue(int x, int y) {
+            this.x = x;
+            this.y = y;
+        }
+    }
+
+    @LooselyConsistentValue
+    static value class MyValue {
+        NestedValue v1;
+        @NullRestricted
+        NestedValue v2;
+
+        MyValue(NestedValue v1, NestedValue v2) {
+            this.v1 = v1;
+            this.v2 = v2;
+        }
+    }
+
+    static TestDeadValueTypeFieldOffset test(TestDeadValueTypeFieldOffset vt) {
+        vt = vt.test1();
+        try {
+            vt = vt.test2();
+            throw new RuntimeException();
+        } catch (NullPointerException e) {
+            // Expected.
+        }
+        return vt;
+    }
+
+    public static void main(String[] args) {
+        MyValue val = new MyValue(null, new NestedValue(5, 6));
+        TestDeadValueTypeFieldOffset vt = new TestDeadValueTypeFieldOffset(null, val);
+        for (int i = 0; i < 10_000; ++i) {
+            vt = test(vt);
+        }
+    }
+}
