+    @IR(applyIfAnd = {"ValueTypePassFieldsAsArgs", "true", "ValueTypeReturnedAsFields", "false"}, counts = {IRNode.CMP_P_OR_N, "2"})
+    @IR(applyIfAnd = {"ValueTypePassFieldsAsArgs", "false", "ValueTypeReturnedAsFields", "false"}, counts = {IRNode.CMP_P_OR_N, "3"})
+    public static void test2() {
