+        Asserts.assertEquals(long8Value.getLongField1(), 1L, "Field 1 incorrect");
+        Asserts.assertEquals(long8Value.getLongField8(), 8L, "Field 8 incorrect");
+        Long8Value.check(long8Value, 1, 2, 3, 4, 5, 6, 7, 8);
+    }
