+    static void testExecutionStackToFields(Class<?> valueClass, Class<?> containerClass) throws Throwable {
+        final int ITERATIONS = Platform.isDebugBuild() ? 3 : 512;
+        String sig = "()L" + valueClass.getName().replace('.', '/') + ";";
+        final MethodTypeDesc voidReturnClass = MethodTypeDesc.ofDescriptor(sig);
+        final ClassDesc systemClassDesc = classDesc(System.class);
+        final ClassDesc valueClassDesc = classDesc(valueClass);
+        final ClassDesc containerClassDesc = classDesc(containerClass);
+
+        MethodHandle fromExecStackToFields = InstructionHelper.buildMethodHandle(
+                LOOKUP,
+                "execStackToFields",
+                MethodType.methodType(boolean.class),
+                CODE -> {
+                    Label loop = CODE.newLabel();
+                    Label end = CODE.newLabel();
+                    Label failed = CODE.newLabel();
+                    CODE
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"), false)
+                    .new_(containerClassDesc)
+                    .dup()
+                    .invokespecial(containerClassDesc, "<init>", MethodTypeDesc.ofDescriptor("()V"))
+                    .astore(1)
+                    .iconst_m1()
+                    .istore(2)
+                    .labelBinding(loop)
+                    .iload(2)
+                    .ldc(ITERATIONS)
+                    .if_icmpeq(end)
+                    .aload(1)
+                    .invokestatic(valueClassDesc, "getInstance", voidReturnClass)
+                    .putfield(containerClassDesc, "nonStaticValueField", valueClassDesc)
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"))
+                    .aload(1)
+                    .getfield(containerClassDesc, "nonStaticValueField", valueClassDesc)
+                    .invokevirtual(valueClassDesc, "verify", MethodTypeDesc.ofDescriptor("()Z"))
+                    .iconst_1()
+                    .if_icmpne(failed)
+                    .aload(1)
+                    .invokestatic(valueClassDesc, "getNonBufferedInstance", voidReturnClass)
+                    .putfield(containerClassDesc, "nonStaticValueField", valueClassDesc)
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"))
+                    .aload(1)
+                    .getfield(containerClassDesc, "nonStaticValueField", valueClassDesc)
+                    .invokevirtual(valueClassDesc, "verify", MethodTypeDesc.ofDescriptor("()Z"))
+                    .iconst_1()
+                    .if_icmpne(failed)
+                    .invokestatic(valueClassDesc, "getInstance", voidReturnClass)
+                    .putstatic(containerClassDesc, "staticValueField", valueClassDesc)
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"))
+                    .getstatic(containerClassDesc, "staticValueField", valueClassDesc)
+                    .checkcast(valueClassDesc)
+                    .invokevirtual(valueClassDesc, "verify", MethodTypeDesc.ofDescriptor("()Z"))
+                    .iconst_1()
+                    .if_icmpne(failed)
+                    .invokestatic(valueClassDesc, "getNonBufferedInstance", voidReturnClass)
+                    .putstatic(containerClassDesc, "staticValueField", valueClassDesc)
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"))
+                    .getstatic(containerClassDesc, "staticValueField", valueClassDesc)
+                    .checkcast(valueClassDesc)
+                    .invokevirtual(valueClassDesc, "verify", MethodTypeDesc.ofDescriptor("()Z"))
+                    .iconst_1()
+                    .if_icmpne(failed)
+                    .iinc(2, 1)
+                    .goto_(loop)
+                    .labelBinding(end)
+                    .iconst_1()
+                    .return_(TypeKind.BOOLEAN)
+                    .labelBinding(failed)
+                    .iconst_0()
+                    .return_(TypeKind.BOOLEAN);
+                });
+        boolean result = (boolean) fromExecStackToFields.invokeExact();
+        System.out.println(result);
+        assertTrue(result, "Invariant");
+    }
+
+    static void testExecutionStackToValueArray(Class<?> valueClass, Class<?> containerClass) throws Throwable {
+        final int ITERATIONS = Platform.isDebugBuild() ? 3 : 100;
+        String sig = "()L" + valueClass.getName().replace('.', '/') + ";";
+        final MethodTypeDesc voidReturnClass = MethodTypeDesc.ofDescriptor(sig);
+        final ClassDesc systemClassDesc = classDesc(System.class);
+        final ClassDesc valueClassDesc = classDesc(valueClass);
+        final ClassDesc containerClassDesc = classDesc(containerClass);
+
+        MethodHandle fromExecStackToValueArray = InstructionHelper.buildMethodHandle(
+                LOOKUP,
+                "execStackToValueArray",
+                MethodType.methodType(boolean.class),
+                CODE -> {
+                    Label loop1 = CODE.newLabel();
+                    Label loop2 = CODE.newLabel();
+                    Label end1 = CODE.newLabel();
+                    Label end2 = CODE.newLabel();
+                    Label failed = CODE.newLabel();
+                    CODE
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"))
+                    .new_(containerClassDesc)
+                    .dup()
+                    .invokespecial(containerClassDesc, "<init>", MethodTypeDesc.ofDescriptor("()V"))
+                    .astore(1)
+                    .ldc(ITERATIONS * 3)
+                    .anewarray(valueClassDesc)
+                    .astore(2)
+                    .aload(2)
+                    .aload(1)
+                    .swap()
+                    .putfield(containerClassDesc, "valueArray", valueClassDesc.arrayType())
+                    .iconst_0()
+                    .istore(3)
+                    .labelBinding(loop1)
+                    .iload(3)
+                    .ldc(ITERATIONS *3)
+                    .if_icmpge(end1)
+                    .aload(2)
+                    .iload(3)
+                    .invokestatic(valueClassDesc, "getInstance", voidReturnClass)
+                    .aastore()
