+                    .iinc(3, 1)
+                    .goto_(loop1)
+                    .labelBinding(end1)
+                    .invokestatic(systemClassDesc, "gc", MethodTypeDesc.ofDescriptor("()V"))
+                    .iconst_0()
+                    .istore(3)
+                    .labelBinding(loop2)
+                    .iload(3)
