+                    .labelBinding(end2)
+                    .iconst_1()
+                    .return_(TypeKind.BOOLEAN)
+                    .labelBinding(failed)
+                    .iconst_0()
+                    .return_(TypeKind.BOOLEAN);
+                });
+        boolean result = (boolean) fromExecStackToValueArray.invokeExact();
+        System.out.println(result);
